INSERT INTO "designers" VALUES(1,'Louis Vuitton','louis-vuitton','LOO-ee vwee-TAWN/','/api/assets/audio/1771070938157-Louis_Vuitton.mp3','Named after Louis Vuitton, the French trunk maker who founded the house.','/api/assets/images/1771070890802-Louis-Vuitton-Horizons-Never-End-00.jpg','Louis Vuitton','1854','Paris, France','Nicolas Ghesquière & Pharrell Williams','[{"name":"Luxury","description":""},{"name":"Heritage","description":""},{"name":"Logo centric","description":""},{"name":"Artisanal","description":""}]','[{"title":"Heritage & Leather Goods Expansion","year_range":"1854 - 1996","description":"From its origins as a Parisian trunk maker, Louis Vuitton built a reputation on innovation in travel and leather craftsmanship. Over the decades, the house evolved from flat-topped trunks to soft luggage and everyday city bags, embedding the Monogram and Damier canvases into global luxury culture while maintaining its foundation in utility, durability, and refinement.","images":["/api/assets/images/1771085832312-ftcms_0725d586-2167-42e5-a5c2-c3aa5a54ffd6.avif","/api/assets/images/1771085836773-50s_vuitton_monogram_large.jpg","/api/assets/images/1771085842407-1950S-AND-60S-683x1024.webp","/api/assets/images/1771085848450-bc4d6f63f5482a8d1d6b8786ac7142fd.jpg","/api/assets/images/1771085852568-catherine-deneuve-actress-and-husband-fashion-photographer-news-photo-1669047710.avif","/api/assets/images/1771085857155-feee325c173dfe629cb300b6e9ad16cc.jpg","/api/assets/images/1771085861002-ftcms_639da5ee-e5ef-437b-8b98-87ed98410da6.avif","/api/assets/images/1771085874619-twiggy-holding-louis-vuitton-bag-1967-photo-bert-stern.jpg"],"image_url":"/api/assets/images/1771085832312-ftcms_0725d586-2167-42e5-a5c2-c3aa5a54ffd6.avif","caption":"From its origins as a Parisian trunk maker, Louis Vuitton built a reputation on innovation in travel and leather craftsmanship. Over the decades, the house evolved from flat-topped trunks to soft luggage and everyday city bags, embedding the Monogram and Damier canvases into global luxury culture while maintaining its foundation in utility, durability, and refinement."},{"title":"Marc Jacobs Era","year_range":"1997 - 2013","description":"With Marc Jacobs’ arrival, Louis Vuitton transformed from a leather goods powerhouse into a full fledged fashion house. Ready-to-wear, runway spectacle, and bold artistic collaborations redefined the brand’s cultural relevance, positioning it at the center of late ’90s and early 2000s luxury innovation.","images":["/api/assets/images/1771085917555-louis-vuitton-fall-2001-ready-to-wear-00030-marcelle-bittar.webp","/api/assets/images/1771085966883-00220h-louis-vuitton-spring-2004-ready-to-wear-rianne-ten-haken.webp","/api/assets/images/1771085977140-00110h-louis-vuitton-spring-2004-ready-to-wear-diana-dondoe.webp","/api/assets/images/1771086012413-00500h-louis-vuitton-spring-2004-ready-to-wear-jessica-stam.webp","/api/assets/images/1771086026351-00030h-louis-vuitton-spring-2004-ready-to-wear-julia-stegner.webp","/api/assets/images/1771086036720-00120fullscreen.webp","/api/assets/images/1771086059645-00360fullscreen.webp","/api/assets/images/1771086064666-00400fullscreen.webp","/api/assets/images/1771086070841-00450fullscreen.webp","/api/assets/images/1771086083634-00140fullscreen.webp"],"image_url":"/api/assets/images/1771085917555-louis-vuitton-fall-2001-ready-to-wear-00030-marcelle-bittar.webp","caption":"With Marc Jacobs’ arrival, Louis Vuitton transformed from a leather goods powerhouse into a full fledged fashion house. Ready-to-wear, runway spectacle, and bold artistic collaborations redefined the brand’s cultural relevance, positioning it at the center of late ’90s and early 2000s luxury innovation."},{"title":"The Collaboration Era","year_range":"2001 - 2012","description":"During Marc Jacobs'' era, Louis Vuitton blurred the boundaries between art, fashion, and pop culture. Partnerships with contemporary artists reimagined the Monogram, turning heritage codes into collectible statements and ushering in a new era of cultural cross-pollination within luxury.","images":["/api/assets/images/1771086544055-1217-VO-FASH04-03.webp","/api/assets/images/1771086555499-louis-vuitton-spring-2001-0.webp","/api/assets/images/1771086584623-952463456.webp","/api/assets/images/1771086592395-Louis-Vuitton-Takashi-Murakami1.webp","/api/assets/images/1771086602584-LV_x_Murakami_GettyImages-113930686.webp","/api/assets/images/1771086614585-b7bf7dba139f76460af8e14a5780e2e7.jpg","/api/assets/images/1771086619094-louis-vuitton-yayoi-kusama-collection-09.jpg","/api/assets/images/1771086623534-original_2_.webp","/api/assets/images/1771086629138-original_1_.webp"],"image_url":"/api/assets/images/1771086544055-1217-VO-FASH04-03.webp","caption":"During Marc Jacobs'' era, Louis Vuitton blurred the boundaries between art, fashion, and pop culture. Partnerships with contemporary artists reimagined the Monogram, turning heritage codes into collectible statements and ushering in a new era of cultural cross-pollination within luxury."},{"title":"Nicolas Ghesquière Era","year_range":"2013 - Present","description":"Under Nicolas Ghesquière, the house embraced a futuristic elegance rooted in structure and precision. Architectural silhouettes, refined leather innovation, and destination runway presentations reasserted Louis Vuitton’s authority in modern womenswear while honoring its heritage foundations.","images":["/api/assets/images/1771086831277-https_hypebeast.com_wp-content_blogs.dir_6_files_2021_10_louis-vuitton-spring-summer-2022-collection-runway-protestor-1.avif","/api/assets/images/1771086835887-louis-vuitton-rtw-ss23-pfw0001.webp","/api/assets/images/1771086840289-LV-SS23-Look_46.jpg","/api/assets/images/1771086845228-LV_FW24_Look_07-683x1024.jpg","/api/assets/images/1771086849040-lv-fw24-look-13-65e892dd2e375.avif","/api/assets/images/1771086852681-vuitton-f24-015-65e792d9e7328.avif","/api/assets/images/1771086856032-vuitton-f24-031-65e792e0ed4a1.avif","/api/assets/images/1771086892760-LV-FW-2020-44.jpg"],"image_url":"/api/assets/images/1771086831277-https_hypebeast.com_wp-content_blogs.dir_6_files_2021_10_louis-vuitton-spring-summer-2022-collection-runway-protestor-1.avif","caption":"Under Nicolas Ghesquière, the house embraced a futuristic elegance rooted in structure and precision. Architectural silhouettes, refined leather innovation, and destination runway presentations reasserted Louis Vuitton’s authority in modern womenswear while honoring its heritage foundations."},{"title":"Men’s Wear Era: Virgil Abloh & Pharrell Williams","year_range":"2018 - Present","description":"Louis Vuitton menswear entered a culture driven phase that merged street influence with luxury craftsmanship. From Virgil Abloh’s conceptual storytelling to Pharrell Williams’ sharpened, celebrity-infused polish, the men’s line expanded the brand’s dialogue beyond fashion into music, art, and global identity.","images":["/api/assets/images/1771087041249-ss19-3.jpeg","/api/assets/images/1771087044457-VuittonPFWSS2019_16.webp","/api/assets/images/1771087048501-gettyimages-980352902-1529599384.jpg","/api/assets/images/1771087053540-1682678354-louis-vuitton-virgil-abloh-runway-show-fw22-collection-38.avif","/api/assets/images/1771087056758-29170840-gettyimages-1200078153_cover_1200x1800.jpg","/api/assets/images/1771087059555-1050242-800w.jpg","/api/assets/images/1771087184000-https_hypebeast.com_wp-content_blogs.dir_6_files_2023_06_pharrell-williams-louis-vuitton-ss24-debut-runway-collection-001.avif","/api/assets/images/1771087190446-230621011404-04-louis-vuitton-pharrell-williams-debut.jpg","/api/assets/images/1771087193607-3571f5f1-8bbf-41e5-870d-1cd11d62dedf-getty-1258879947.avif","/api/assets/images/1771087211234-65a9876553146b9b399bc7f9_FLAUNT_LVMENS23.webp","/api/assets/images/1771087214878-LV-1600x2000-JANV24-05.avif","/api/assets/images/1771087219276-RED0578_LOOK25_11zon-scaled.jpg","/api/assets/images/1771087223944-Vuitton_m_F24_012.webp"],"image_url":"/api/assets/images/1771087041249-ss19-3.jpeg","caption":"Louis Vuitton menswear entered a culture driven phase that merged street influence with luxury craftsmanship. From Virgil Abloh’s conceptual storytelling to Pharrell Williams’ sharpened, celebrity-infused polish, the men’s line expanded the brand’s dialogue beyond fashion into music, art, and global identity."}]','[{"name":"Speedy Soft 30","image_url":"/api/assets/images/1771087455332-louis-vuitton-speedy-soft-30--M27387_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/lv-x-tm-speedy-soft-30-other-leathers-nvprod7270124v/M27387"},{"name":"Nano Noé","image_url":"/api/assets/images/1771087516821-louis-vuitton-nano-noe--M27699_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/nano-noe-autres-toiles-monogram-nvprod7220029v/M27699"},{"name":"Keepall Cargo 50","image_url":"/api/assets/images/1771087615583-louis-vuitton-keepall-cargo-50--M14735_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/keepall-cargo-50-g69-nvprod6260217v/M14735"},{"name":"Talisman Open Toe High Boot","image_url":"/api/assets/images/1771087666025-louis-vuitton-talisman-open-toe-high-boot--AVR05OLK02_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/talisman-open-toe-high-boot-nvprod6600045v/1AJOGC"},{"name":"Topstitched Hoodie Dress","image_url":"/api/assets/images/1771087745015-louis-vuitton-topstitched-hoodie-dress--FUJD99V71651_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/topstitched-hoodie-dress-nvprod6970031v/1AJEO4"},{"name":"Belted Double-Breasted Jacket","image_url":"/api/assets/images/1771087770353-louis-vuitton-belted-double-breasted-jacket--FUJC14NCB214_PM2_Front_view.avif","link":"https://eu.louisvuitton.com/eng-e1/products/belted-double-breasted-jacket-nvprod7280052v/1AJGPV"}]','2026-02-14 12:10:32','2026-02-14 17:02:35');
INSERT INTO "designers" VALUES(2,'Gucci','gucci','GOO-chee','/api/assets/audio/1771088878513-Gucci.mp3','Named after founder Guccio Gucci; the surname “Gucci” is Tuscan Italian. The brand began as a leather goods and luggage house inspired by aristocratic travel culture.','/api/assets/images/1771088926228-GUCCI_020_0251_EXT_v5_QC_R72dpi.jpg','Guccio Gucci','1921','Florence, Italy','Demna','[{"name":"Luxury","description":""},{"name":"Glamour","description":""},{"name":"Maximalist","description":""},{"name":"Eclectic","description":""}]','[{"title":"Heritage to Global Status","year_range":"1921 - 1993","description":"From Florence leathercraft to jet set visibility, Gucci establishes its core codes: bamboo, horsebit hardware, and the web stripe, then expands into a symbol driven, logo forward era that makes the house globally recognizable, even as creative consistency shifts across decades.","images":["/api/assets/images/1771089741607-House-of-Gucci-Timeline-008.webp","/api/assets/images/1771089745148-House-of-Gucci-Timeline-012.webp","/api/assets/images/1771089748033-House-of-Gucci-Timeline-017.webp","/api/assets/images/1771089751509-House-of-Gucci-Timeline-018.webp","/api/assets/images/1771089754363-House-of-Gucci-Timeline-019.webp","/api/assets/images/1771089757623-House-of-Gucci-Timeline-023.webp","/api/assets/images/1771089761086-House-of-Gucci-Timeline-047.webp","/api/assets/images/1771089764907-206ebaf4665c87e47449d1a69220b68b.jpg"],"image_url":"/api/assets/images/1771089741607-House-of-Gucci-Timeline-008.webp","caption":"From Florence leathercraft to jet set visibility, Gucci establishes its core codes: bamboo, horsebit hardware, and the web stripe, then expands into a symbol driven, logo forward era that makes the house globally recognizable, even as creative consistency shifts across decades."},{"title":"Sex & Power Reinvention","year_range":"1994 - 2004","description":"Under Tom Ford, Gucci crystallizes into a high gloss fantasy of modern desire: sharp tailoring, 70s sensuality, and provocative imagery that repositions the house as the defining luxury mood of the late 90s and early 2000s.","images":["/api/assets/images/1771090127409-GettyImages-1441079223_916124.webp","/api/assets/images/1771090130400-fall96_1.webp","/api/assets/images/1771090133608-GUCCI-FALL-1995-RTW-01-AMBER-VALLETTA.webp","/api/assets/images/1771090136824-GUCCI-FALL-1995-RTW-02-SHALOM-HARLOW.webp","/api/assets/images/1771090140061-GUCCI-FALL-1996-RTW-01-KATE-MOSS.webp","/api/assets/images/1771090148195-GUCCI-FALL-1996-43-GEORGINA-GRENVILLE.jpg","/api/assets/images/1771090151105-GUCCI-FALL-1996-48-KATE-MOSS.jpg"],"image_url":"/api/assets/images/1771090127409-GettyImages-1441079223_916124.webp","caption":"Under Tom Ford, Gucci crystallizes into a high gloss fantasy of modern desire: sharp tailoring, 70s sensuality, and provocative imagery that repositions the house as the defining luxury mood of the late 90s and early 2000s."},{"title":"New Gucci: Maximalism to Reset","year_range":"2015 - 2022","description":"Under Alessandro Michele, Gucci becomes a cultural engine: romantic, eclectic, and intentionally excessive, layering vintage references, gender-fluid styling, and ornate embellishment into a maximalist universe that redefined 2010s luxury.","images":["/api/assets/images/1771090541664-alessandro-michele-valentino.jpg","/api/assets/images/1771090545069-gucci-017-1366.JPG","/api/assets/images/1771090550246-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_11_alessandro-michele-gucci-best-moments-1.avif","/api/assets/images/1771090554829-https_hypebeast.com_image_2018_02_gucci-2018-fall-winter-44.avif","/api/assets/images/1771090558872-alessandro-michele-top-moments-gucci-designboom-01.jpg","/api/assets/images/1771090561970-gucci40.avif","/api/assets/images/1771090565831-https_hypebeast.com_wp-content_blogs.dir_6_files_2019_02_gucci-fall-winter-2019-milan-fashion-week-23.avif","/api/assets/images/1771090569946-alessandro-michele-top-moments-gucci-designboom-06.jpg","/api/assets/images/1771090573522-alessandro-michele-top-moments-gucci-designboom-07.jpg"],"image_url":"/api/assets/images/1771090541664-alessandro-michele-valentino.jpg","caption":"Under Alessandro Michele, Gucci becomes a cultural engine: romantic, eclectic, and intentionally excessive, layering vintage references, gender-fluid styling, and ornate embellishment into a maximalist universe that redefined 2010s luxury."},{"title":"Demna Era","year_range":"2025 - Now","description":"With Demna appointed Creative Director, Gucci enters a new chapter poised to reinterpret its iconography through a sharper, more contemporary lens, balancing provocation and structure as the house seeks renewed cultural authority.","images":["/api/assets/images/1771090919927-00002-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090922616-00008-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090925250-00012-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090927547-00014-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090929835-00020-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090932276-00029-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090935499-00036-gucci-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771090939452-00006-gucci-pre-fall-2026-credit-brand.webp","/api/assets/images/1771090943614-00007-gucci-pre-fall-2026-credit-brand.webp","/api/assets/images/1771090947483-00009-gucci-pre-fall-2026-credit-brand.webp","/api/assets/images/1771090955216-00017-gucci-pre-fall-2026-credit-brand.webp","/api/assets/images/1771090957849-00019-gucci-pre-fall-2026-details-credit-brand.webp","/api/assets/images/1771090961002-00035-gucci-pre-fall-2026-credit-brand.webp"],"image_url":"/api/assets/images/1771090919927-00002-gucci-spring-2026-ready-to-wear-credit-brand.webp","caption":"With Demna appointed Creative Director, Gucci enters a new chapter poised to reinterpret its iconography through a sharper, more contemporary lens, balancing provocation and structure as the house seeks renewed cultural authority."}]','[{"name":"Gucci Bamboo 1947 Bag","image_url":"/api/assets/images/1771091259394-P01151157.avif","link":"https://www.mytheresa.com/euro/en/women/gucci-gucci-bamboo-1947-medium-top-handle-bag-black-p01151157"},{"name":"Double G Wool Jacket","image_url":"/api/assets/images/1771091279131-P01150105.avif","link":"https://www.mytheresa.com/euro/en/women/gucci-double-g-cropped-wool-crepe-jacket-black-p01150105"},{"name":"Signora Horsebit 110 Shoes","image_url":"/api/assets/images/1771091311978-P01154785.webp","link":"https://www.mytheresa.com/euro/en/women/gucci-zhora-gucci-horsebit-120-leather-pumps-black-p01154785"},{"name":"GG printed Silk Scarf","image_url":"/api/assets/images/1771091334457-P01151188.avif","link":"https://www.mytheresa.com/euro/en/women/gucci-gg-printed-silk-twill-scarf-beige-p01151188"},{"name":"Gucci Jackie 1961 Bag","image_url":"/api/assets/images/1771091404491-P01151159_1_.avif","link":"https://www.mytheresa.com/euro/en/women/gucci-gucci-jackie-1961-small-canvas-shoulder-bag-beige-p01151159"},{"name":"Signora Horsebit Boots","image_url":"/api/assets/images/1771091423236-P01154780.avif","link":"https://www.mytheresa.com/euro/en/women/gucci-signora-horsebit-leather-pumps-black-p01154780"}]','2026-02-14 17:50:29','2026-02-14 17:50:29');
INSERT INTO "designers" VALUES(3,'Prada','prada','PRAH-dah','/api/assets/audio/1771091796089-Prada.mp3','Prada is the founding family surname; the business began as Fratelli Prada (“Prada Brothers”)','/api/assets/images/1771091840916-hero_DT.avif','Mario & Martino Prada','1913','Milan, Italy','Miuccia Prada & Raf Simons','[{"name":"Minimalist","description":""},{"name":"Conceptual","description":""},{"name":"Industrial","description":""},{"name":"Luxury","description":""}]','[{"title":"Miuccia Reset: Nylon & Anti-Luxury","year_range":"1978 - 1994","description":"Prada pivots from legacy leather goods into intellectual minimalism under Miuccia Prada. Industrial nylon and stripped back silhouettes challenge traditional ideas of glamour, establishing Prada as conceptual rather than decorative.","images":["/api/assets/images/1771098585489-1MlODTdw_o.jpeg","/api/assets/images/1771098587353-62xFhqGn_o.jpeg","/api/assets/images/1771098589492-aewlLbpd_o.jpeg","/api/assets/images/1771098591484-aRfbNi1W_o.jpeg","/api/assets/images/1771098595730-D897Xv55_o.jpeg","/api/assets/images/1771098597943-hvQWGI68_o.jpeg","/api/assets/images/1771098600530-hxSTSPSP_o.jpeg","/api/assets/images/1771098603110-qJHqHaiG_o.jpeg","/api/assets/images/1771098605800-uAiQhhu9_o.jpeg","/api/assets/images/1771098609823-y9CMi5pf_o.jpeg"],"image_url":"/api/assets/images/1771098585489-1MlODTdw_o.jpeg","caption":"Prada pivots from legacy leather goods into intellectual minimalism under Miuccia Prada. Industrial nylon and stripped back silhouettes challenge traditional ideas of glamour, establishing Prada as conceptual rather than decorative."},{"title":"Intellectual 90s Prada: Ugly Chic Goes Global","year_range":"1995 - 2004","description":"Prada refines awkward elegance into a cultural language. Sharp tailoring, off beat color palettes, and calculated restraint make the brand a uniform for thinkers and creatives.","images":["/api/assets/images/1771098850236-365101.avif","/api/assets/images/1771098853714-PRADA-SPRING-1996-RTW-04-SHALOM-HARLOW.webp","/api/assets/images/1771098858740-365100.avif","/api/assets/images/1771098861421-Prada_FW_1996_-_Look_13.jpeg","/api/assets/images/1771098864783-022.avif","/api/assets/images/1771098869157-006.avif","/api/assets/images/1771098872825-004.avif","/api/assets/images/1771098876221-PRADA-FALL-2000-RTW-15-MAGGIE-RIZER-2D3T0446.webp","/api/assets/images/1771098879388-PRADA-FALL-2000-RTW-05-HANNELORE-KNUTS-2D3T0398.webp"],"image_url":"/api/assets/images/1771098850236-365101.avif","caption":"Prada refines awkward elegance into a cultural language. Sharp tailoring, off beat color palettes, and calculated restraint make the brand a uniform for thinkers and creatives."},{"title":"Codified Prada","year_range":"2005 - 2019","description":"Prada expands its commercial power while reinforcing house codes. Accessories become pillars, and archival elements are modernized for a new generation.","images":["/api/assets/images/1771099240962-_J9D0018.1366x2048.webp","/api/assets/images/1771099244210-005.avif","/api/assets/images/1771099247124-Prada_FW_2013_-_Look_12.jpg","/api/assets/images/1771099249223-Prada_FW_2013_-_Look_16.jpg","/api/assets/images/1771099251402-Prada_FW_2013_-_Look_18.jpg","/api/assets/images/1771099253790-prada-rf18-5847.jpg","/api/assets/images/1771099255822-prada-rf18-5856.jpg","/api/assets/images/1771099259002-prada-rf18-5928.jpg"],"image_url":"/api/assets/images/1771099240962-_J9D0018.1366x2048.webp","caption":"Prada expands its commercial power while reinforcing house codes. Accessories become pillars, and archival elements are modernized for a new generation."},{"title":"Dual Authorship: Miuccia & Raf","year_range":"2020 - Present","description":"Prada formalizes dual authorship, balancing heritage with progressive tailoring and modern uniform dressing. The brand sharpens its dialogue between classicism and experimentation.","images":["/api/assets/images/1771099371812-BjltWKLK-Prada-Donna-SS21_027-min-1200x1800.jpg","/api/assets/images/1771099378674-007.avif","/api/assets/images/1771099381756-004.avif","/api/assets/images/1771099384762-001.avif","/api/assets/images/1771099388880-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_02_prada-fall-winter-womenswear-milan-fashion-week-raf-simmons-miuccia-prada-017.avif","/api/assets/images/1771099393708-prada-milano-fall-2022-05.webp","/api/assets/images/1771099396098-28-pradadonnafw22-c48f06.webp","/api/assets/images/1771099398659-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_02_prada-fall-winter-womenswear-milan-fashion-week-raf-simmons-miuccia-prada-014.avif"],"image_url":"/api/assets/images/1771099371812-BjltWKLK-Prada-Donna-SS21_027-min-1200x1800.jpg","caption":"Prada formalizes dual authorship, balancing heritage with progressive tailoring and modern uniform dressing. The brand sharpens its dialogue between classicism and experimentation."}]','[{"name":"Suede Jacket","image_url":"/api/assets/images/1771146741886-P01158643.avif","link":"https://www.mytheresa.com/euro/en/women/prada-suede-jacket-brown-p01158643"},{"name":"Prada Bonnie Bag","image_url":"/api/assets/images/1771146775856-P00952994.webp","link":"https://www.mytheresa.com/euro/en/women/prada-soft-lux-small-leather-shoulder-bag-black-p00952994"},{"name":"Belted Midi Skirt","image_url":"/api/assets/images/1771146808926-P01117226.avif","link":"https://www.mytheresa.com/euro/en/women/prada-belted-midi-skirt-green-p01117226"},{"name":"Re-Edition Suede Shoulder Bag","image_url":"/api/assets/images/1771146869295-P01161829.avif","link":"https://www.mytheresa.com/euro/en/women/prada-prada-re-edition-suede-shoulder-bag-brown-p01161829"},{"name":"55 Leather Slingback Pumps","image_url":"/api/assets/images/1771146905945-P01133390.avif","link":"https://www.mytheresa.com/euro/en/women/prada-55-patent-leather-slingback-pumps-red-p01133390"},{"name":"Re-Nylon Belted Minidress","image_url":"/api/assets/images/1771146937334-P01151390.avif","link":"https://www.mytheresa.com/euro/en/women/prada-re-nylon-belted-zip-up-minidress-black-p01151390"}]','2026-02-14 20:03:21','2026-02-15 09:15:44');
INSERT INTO "designers" VALUES(4,'Saint Laurent','saint-laurent','san lo-RAHN','/api/assets/audio/1771147146590-Saint_Laurent.mp3',replace('Named after founder Yves Saint Laurent. \nThe house dropped “Yves” from ready-to-wear branding in 2012 under Hedi Slimane.','\n',char(10)),'/api/assets/images/1771147233477-Saint-Laurent-Summer-Ad-Campaign-2025-The-Impression-003-scaled.jpg','Yves Saint Laurent and Pierre Bergé','1961','Paris, France','Anthony Vaccarello','[{"name":"Tailoring","description":""},{"name":"Glamour","description":""},{"name":"Androgynous","description":""},{"name":"Minimalist","description":""}]','[{"title":"The Revolutionary Couture Era","year_range":"1961 - 1976","description":"Saint Laurent redefines modern dressing by merging couture craft with radical cultural cues. The house democratizes style through Rive Gauche and challenges gender codes, positioning fashion as social commentary as much as luxury.","images":["/api/assets/images/1771149143753-58528d9b6666b2eb47629243_yves-saint-laurent-couture-5.avif","/api/assets/images/1771149146855-NUM_HC1966H076PH01.01267.jpg","/api/assets/images/1771149149765-0c451dbf63c3d4ff7b5dcc86888b7edf.jpg","/api/assets/images/1771149152070-1_IzTeUB0V9t9CvARUAHwCfg.jpg","/api/assets/images/1771149156934-Safari.jpg","/api/assets/images/1771149165745-b2cee918-0276-496e-bee5-196529a432a4_1420x1956.jpg","/api/assets/images/1771149169304-c0ac23660e330d9066d455970885aa69.jpg","/api/assets/images/1771149172255-SIPA_00090430_00000777.jpg","/api/assets/images/1771149177932-a51b539517cb2be5fe3bbe1f106d097a.jpg","/api/assets/images/1771149182483-ysl-13.jpg"],"image_url":"/api/assets/images/1771149143753-58528d9b6666b2eb47629243_yves-saint-laurent-couture-5.avif","caption":"Saint Laurent redefines modern dressing by merging couture craft with radical cultural cues. The house democratizes style through Rive Gauche and challenges gender codes, positioning fashion as social commentary as much as luxury."},{"title":"Heritage & Transition","year_range":"1977 - 1998","description":"As the founder consolidates his legacy, the brand balances opulence with commercial expansion. Couture remains a symbol of Parisian authority while ready-to-wear grows globally, reinforcing Saint Laurent as a pillar of French luxury before its corporate transition.","images":["/api/assets/images/1771149510750-72afb646d11c8747a27d4590de6c4b9a.jpg","/api/assets/images/1771149515411-102b2bdcb1fceca24225aec25ac6306a.jpg","/api/assets/images/1771149517551-d43089219b6be87a389e63d260804911.jpg","/api/assets/images/1771149520157-e914e113ba890fa48cfaab7c82115e32.jpg","/api/assets/images/1771149522485-003-YSL-History-VogueINT-Sep19-Getty-Images.webp","/api/assets/images/1771149525270-2ace94ae5abab574361981c30edbbbc6.jpg","/api/assets/images/1771149529489-005-YSL-History-VogueINT-Sep19-Getty-Images.webp","/api/assets/images/1771149531636-004-YSL-History-VogueINT-Sep19-Getty-Images.webp"],"image_url":"/api/assets/images/1771149510750-72afb646d11c8747a27d4590de6c4b9a.jpg","caption":"As the founder consolidates his legacy, the brand balances opulence with commercial expansion. Couture remains a symbol of Parisian authority while ready-to-wear grows globally, reinforcing Saint Laurent as a pillar of French luxury before its corporate transition."},{"title":"The Gucci Group Repositioning","year_range":"1998 - 2004","description":"As the house enters corporate transition, Saint Laurent moves from late-founder romanticism into a recalibrated luxury identity under Gucci Group control. Alber Elbaz briefly softens the ready-to-wear line with Parisian sensitivity, before Tom Ford decisively sharpens the brand into high gloss sensuality: tight tailoring, nocturnal glamour, and image driven provocation redefining YSL for the early-2000s power era.","images":["/api/assets/images/1771149909627-YVES-SAINT-LAURENT-FALL-2000-RTW-01-HANNELORE-KNUTS-7365.webp","/api/assets/images/1771149911139-YVES-SAINT-LAURENT-FALL-2000-RTW-11-MINI-ANDEN-7409.webp","/api/assets/images/1771149912866-YVES-SAINT-LAURENT-FALL-2000-RTW-14-ERIKA-WALL-7422.webp","/api/assets/images/1771149914705-YVES-SAINT-LAURENT-FALL-2000-RTW-21-ANGELA-LINDVALL-7452.webp","/api/assets/images/1771149917219-YVES-SAINT-LAURENT-FALL-2000-RTW-56-GISELE-BUNDCHEN-7620.webp","/api/assets/images/1771150050955-00030h-saint-laurent-spring-2003-ready-to-wear-omahyra-mota.webp","/api/assets/images/1771150053140-00140h-saint-laurent-spring-2003-ready-to-wear-omahyra-mota.webp","/api/assets/images/1771150055309-00010f.webp","/api/assets/images/1771150058301-735cac15f76d16113a1c21ad97c131f7.jpg","/api/assets/images/1771150062780-9771539da1c865337c6834ea883158ba.jpg"],"image_url":"/api/assets/images/1771149909627-YVES-SAINT-LAURENT-FALL-2000-RTW-01-HANNELORE-KNUTS-7365.webp","caption":"As the house enters corporate transition, Saint Laurent moves from late-founder romanticism into a recalibrated luxury identity under Gucci Group control. Alber Elbaz briefly softens the ready-to-wear line with Parisian sensitivity, before Tom Ford decisively sharpens the brand into high gloss sensuality: tight tailoring, nocturnal glamour, and image driven provocation redefining YSL for the early-2000s power era."},{"title":"The Slimane Reboot","year_range":"2012 - 2016","description":"Under Hedi Slimane, the house sharpens into a rock inflected, youth driven silhouette. Dropping “Yves” for ready-to-wear, Slimane reframes Saint Laurent as lean, nocturnal, and culturally plugged into music and LA subculture.","images":["/api/assets/images/1771150245782-_ARC0006.1366x2048.webp","/api/assets/images/1771150247656-_ARC0026.1366x2048.webp","/api/assets/images/1771150249616-052a.avif","/api/assets/images/1771150252984-182549894_10-820x1232.jpg","/api/assets/images/1771150255336-saint-laurent-002.webp","/api/assets/images/1771150260655-saint-laurent-fall-winter-2014-show9.jpg","/api/assets/images/1771150262925-saint-laurent-rtw-fw2014-runway-05_20051641070.webp","/api/assets/images/1771150265150-saint-laurent-spring-2014-35.jpg"],"image_url":"/api/assets/images/1771150245782-_ARC0006.1366x2048.webp","caption":"Under Hedi Slimane, the house sharpens into a rock inflected, youth driven silhouette. Dropping “Yves” for ready-to-wear, Slimane reframes Saint Laurent as lean, nocturnal, and culturally plugged into music and LA subculture."},{"title":"The Vaccarello Precision Era","year_range":"2016 - Present","description":"Anthony Vaccarello refines the house into sleek, high voltage minimalism. He amplifies sensual tailoring, sharp shoulders, and Parisian night glamour while staging monumental runway spectacles that reinforce Saint Laurent’s architectural authority.","images":["/api/assets/images/1771150492389-00005-saint-laurent-fall-2018-ready-to-wear-credit-indigital-model-hiandra-martinez.webp","/api/assets/images/1771150494156-https_hypebeast.com_wp-content_blogs.dir_6_files_2018_02_saint-laurent-fall-winter-2018-paris-fashion-week-show-13.avif","/api/assets/images/1771150500017-saint-laurent-rtw-fall-2018-paris-fashion-week-03.webp","/api/assets/images/1771150503036-saint-laurent-rtw-spring-2020-paris-fashion-week-pfw-005.webp","/api/assets/images/1771150505394-saint-laurent-spring-summer-2020-1084-1-1200x1800.jpg","/api/assets/images/1771150507141-ysl-ss20.jpg","/api/assets/images/1771150509853-https_hypebeast.com_image_2024_09_24_saint-laurent-ss25-spring-summer-2025-collection-paris-fashion-week-runway-18.avif","/api/assets/images/1771150515041-https_hypebeast.com_image_2018_02_saint-laurent-fall-winter-2018-1.avif","/api/assets/images/1771150517606-00026-saint-laurent-spring-2025-ready-to-wear-credit-gorunway-scaled.webp","/api/assets/images/1771150520728-9896baa7234f2d2aee103ce7e4cbaaca.jpeg","/api/assets/images/1771150525832-saint-laurent-fashion-show-woman-summer25-runway-49-hr-1067x1600.jpg"],"image_url":"/api/assets/images/1771150492389-00005-saint-laurent-fall-2018-ready-to-wear-credit-indigital-model-hiandra-martinez.webp","caption":"Anthony Vaccarello refines the house into sleek, high voltage minimalism. He amplifies sensual tailoring, sharp shoulders, and Parisian night glamour while staging monumental runway spectacles that reinforce Saint Laurent’s architectural authority."}]','[{"name":"Amalia 110 Satin Pumps","image_url":"/api/assets/images/1771162097889-P01159223.avif","link":"https://www.mytheresa.com/euro/en/women/saint-laurent-amalia-110-crepe-satin-slingback-pumps-green-p01159223"},{"name":"Wool Gabardine Blazer","image_url":"/api/assets/images/1771162122581-P01128152.avif","link":"https://www.mytheresa.com/euro/en/women/saint-laurent-wool-gabardine-blazer-brown-p01128152"},{"name":"Amalia Suede Shoulder Bag","image_url":"/api/assets/images/1771162140874-P01145203.avif","link":"https://www.mytheresa.com/euro/en/women/saint-laurent-amalia-suede-shoulder-bag-brown-p01145203"},{"name":"","image_url":"","link":""},{"name":"Jeanne 75 Leather Pumps","image_url":"/api/assets/images/1771162200491-P01163662.avif","link":"https://www.mytheresa.com/euro/en/women/saint-laurent-jeanne-75-leather-slingback-pumps-black-p01163662"},{"name":"Leather bomber jacket","image_url":"/api/assets/images/1771162171437-P01086651.avif","link":"https://www.mytheresa.com/euro/en/women/saint-laurent-oversized-leather-jacket-brown-p01086651"}]','2026-02-15 13:30:06','2026-02-15 13:30:06');
INSERT INTO "designers" VALUES(5,'Balenciaga','balenciaga','buh-len-see-AH-guh','/api/assets/audio/1771162362096-Balenciaga_2.mp3','Named after founder Cristóbal Balenciaga, the house carries his Basque surname.','/api/assets/images/1771162536765-5Z4CO25F5RES7AUHKGNEXKWJ24.avif','Cristóbal Balenciaga','1917','Paris, France ','Pierpaolo Piccioli','[{"name":"Avant-garde","description":""},{"name":"Sculptural","description":""},{"name":"Couture","description":""},{"name":"Streetwear","description":""}]','[{"title":"The Master of Form ","year_range":"1917 - 1968","description":"Cristóbal Balenciaga establishes himself as a couturier’s couturier, refining sculptural silhouettes and architectural volume. The house becomes synonymous with purity of line and uncompromising construction, influencing generations of designers and redefining mid-century couture.","images":["/api/assets/images/1771163138679-3f2a48760fbd073575442a4b86e7abf1.jpg","/api/assets/images/1771163140990-5a4e42ce1bf73166461f195f967f22f7.jpg","/api/assets/images/1771163143298-39ae327db1a8a21eb75ba18407d1a6bf.jpg","/api/assets/images/1771163146105-934bda19f678595de5874dcc724d324d.jpg","/api/assets/images/1771163148440-1211506.avif","/api/assets/images/1771163150291-1617703501-balenciaga-evening-cape-dress.webp","/api/assets/images/1771163152551-Irving_Penn_Sue_Murray_in_Balenciaga_Vogue_September_1967_-_JPG.jpg","/api/assets/images/1771163155060-lisa-fonssagrives-penn-wearing-coat-by-cristc3b3bal-balenciaga-paris-1950-photograph-by-irving-penn-c2a9-condc3a9-nast-irving-penn-foundation.webp","/api/assets/images/1771163157376-unnamed_9_.jpg"],"image_url":"/api/assets/images/1771163138679-3f2a48760fbd073575442a4b86e7abf1.jpg","caption":"Cristóbal Balenciaga establishes himself as a couturier’s couturier, refining sculptural silhouettes and architectural volume. The house becomes synonymous with purity of line and uncompromising construction, influencing generations of designers and redefining mid-century couture."},{"title":"Revival & Ready-to-Wear Reset","year_range":"1986 - 2014","description":"After years of dormancy following the founder’s 1968 retirement and death in 1972, the house reawakens under new ownership. Creative directors including Nicolas Ghesquière modernize the archive, fusing futurism with heritage and reposition Balenciaga as an intellectual, directional force in luxury ready-to-wear.","images":["/api/assets/images/1771163361810-3537073760_93dcbafd6f_o_1_master.jpg","/api/assets/images/1771163363829-BALENCIAGA-SPRING-1998-RTW-04.webp","/api/assets/images/1771163366008-BALENCIAGA-SPRING-1998-RTW-06.webp","/api/assets/images/1771163367884-BALENCIAGA-SPRING-1998-RTW-26-AURELIE-CLAUDEL.webp","/api/assets/images/1771163370431-00010h-balenciaga-fall-2006-ready-to-wear-hilary-rhoda.webp","/api/assets/images/1771163372957-00050h-balenciaga-fall-2006-ready-to-wear-bianca-balti.webp","/api/assets/images/1771163374768-00070h-balenciaga-fall-2006-ready-to-wear-anne-catherine-lacroix.webp","/api/assets/images/1771163378279-00080h-balenciaga-fall-2006-ready-to-wear-raquel-zimmermann.webp"],"image_url":"/api/assets/images/1771163361810-3537073760_93dcbafd6f_o_1_master.jpg","caption":"After years of dormancy following the founder’s 1968 retirement and death in 1972, the house reawakens under new ownership. Creative directors including Nicolas Ghesquière modernize the archive, fusing futurism with heritage and reposition Balenciaga as an intellectual, directional force in luxury ready-to-wear."},{"title":"Postmodern Disruption","year_range":"2015 - 2019","description":"With Demna’s arrival, Balenciaga pivots sharply toward cultural commentary and street-inflected irony. The house interrogates luxury through exaggeration: oversized tailoring, logo manipulation, and normcore subversion, transforming it into one of fashion’s most talked-about brands.","images":["/api/assets/images/1771163553812-14-6c78d5.webp","/api/assets/images/1771163557114-295e0cd6691319b5898b817e797fc23f.jpg","/api/assets/images/1771163558854-balenciaga-fall-2016-rtw-slide-T56Q-articleLarge.webp","/api/assets/images/1771163565925-http_com.ft.imagepublish.upp-prod-eu.s3.amazonaws.avif","/api/assets/images/1771163569087-https_hypebeast.com_wp-content_blogs.dir_6_files_2018_03_balenciaga-fall-winter-2018-pfw-44.avif","/api/assets/images/1771163577055-balenciaga-fall-2018-runway-36.avif","/api/assets/images/1771163580141-balance11.webp","/api/assets/images/1771163582124-8-733f12.webp","/api/assets/images/1771163584545-e693f85843e61a7dd304993d15953c53.jpg"],"image_url":"/api/assets/images/1771163553812-14-6c78d5.webp","caption":"With Demna’s arrival, Balenciaga pivots sharply toward cultural commentary and street-inflected irony. The house interrogates luxury through exaggeration: oversized tailoring, logo manipulation, and normcore subversion, transforming it into one of fashion’s most talked-about brands."},{"title":"Couture Reclaimed & Emotional Precision","year_range":"2020 - Present","description":"Balenciaga reclaims couture in 2021 for the first time since 1968, initially under Demna, restoring the house’s atelier authority. With Pierpaolo Piccioli’s arrival, the narrative pivots again, toward heightened emotion, color discipline, and sculptural romanticism that reconnects more explicitly to Cristóbal’s refinement and architectural purity.","images":["/api/assets/images/1771163735395-00009-Balenciaga-Couture-Fall-21-credit-brand-scaled.jpeg","/api/assets/images/1771163737294-Balenciaga-Couture-Fall-2021-Collection-photo-courtesy-of-BALENCIAGA-57.jpg","/api/assets/images/1771163739330-00002-Balenciaga-Couture-Fall-21-credit-brand.webp","/api/assets/images/1771163741452-HR_00017-Balenciaga-Couture-Fall-21.webp","/api/assets/images/1771163830177-03PFW-BALENCIAGA-22-mobileMasterAt3x.webp","/api/assets/images/1771163832980-balenciaga-santiago-sierra-spring-summer-2023-runway-fashion_dezeen_2364_col_0-1-852x1278.jpg","/api/assets/images/1771163835645-67b3713321634e18bd67cdafea83f907.webp","/api/assets/images/1771163838565-balenciaga-reaction-vogue-business-story.webp","/api/assets/images/1771163842919-Balenciaga-Spring-2026-Looks2.jpg","/api/assets/images/1771163845407-https_hypebeast.com_image_2025_10_05_balenciaga-ss26-paris-fashion-week-runway-show-collection-pierpaolo-piccioli-info-33.avif"],"image_url":"/api/assets/images/1771163735395-00009-Balenciaga-Couture-Fall-21-credit-brand-scaled.jpeg","caption":"Balenciaga reclaims couture in 2021 for the first time since 1968, initially under Demna, restoring the house’s atelier authority. With Pierpaolo Piccioli’s arrival, the narrative pivots again, toward heightened emotion, color discipline, and sculptural romanticism that reconnects more explicitly to Cristóbal’s refinement and architectural purity."}]','[{"name":"Le City Moto Small Shoulder Bag","image_url":"/api/assets/images/1771163914186-P01158204.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-le-city-moto-small-leather-shoulder-bag-black-p01158204"},{"name":"Avenue Fringe Ankle Boots","image_url":"/api/assets/images/1771163956455-P01126050.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-avenue-90-leather-fringe-ankle-boots-black-p01126050"},{"name":"Hourglass Down Jacket","image_url":"/api/assets/images/1771163972997-P01118964.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-hourglass-down-jacket-white-p01118964"},{"name":"Belted Minidress","image_url":"/api/assets/images/1771163991812-P01033713.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-cotton-blend-jersey-minidress-black-p01033713"},{"name":"City Leather Sneakers","image_url":"/api/assets/images/1771164011781-P01137347.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-city-leather-sneakers-black-p01137347"},{"name":"Double-breasted Wool Coat","image_url":"/api/assets/images/1771164057677-P01092724.avif","link":"https://www.mytheresa.com/euro/en/women/balenciaga-double-breasted-wool-coat-black-p01092724"}]','2026-02-15 14:01:01','2026-02-15 14:01:01');
INSERT INTO "designers" VALUES(6,'Versace','versace','ver-SAH-chee','/api/assets/audio/1771168705805-Versace_2.mp3','Versace is the founder’s surname, Gianni Versace’s family name, used as the house name when he launched the label in Milan.','/api/assets/images/1771168861990-hq720.jpg','Gianni Versace','1978','Milan, Italy','Pieter Mulier','[{"name":"Maximalist","description":""},{"name":"Glamour","description":""},{"name":"Logo-centric","description":""},{"name":"Opulent","description":""}]','[{"title":"Gianni’s High Voltage Classicism","year_range":"1978 - 1997","description":"Versace builds a new kind of Italian glamour: classical references and graphic motifs pushed through body conscious tailoring, metalwork, and unapologetic sex appeal. The house becomes a runway to pop culture engine, defining the supermodel era in the process.\n","images":["/api/assets/images/1771169285915-VERSACE-FALL-1991-RTW-04-CINDY-CRAWFORD.webp","/api/assets/images/1771169287733-917de6eaedc10df1f381fce13e34e909.jpg","/api/assets/images/1771169290823-c036494e39021b3d0a60a58564f30517.jpg","/api/assets/images/1771169293434-58d3e9881f5d3351cbfe6d66475e541a.jpg","/api/assets/images/1771169295268-08cabbb5b6a90c2d78b0347c25c199b5.jpg","/api/assets/images/1771169299047-4b68598f0ee1581b3ebd8558ebfbd1cd.jpg","/api/assets/images/1771169307912-YasmeenGhaur-Look50_5000x.webp","/api/assets/images/1771169314816-08cabbb5b6a90c2d78b0347c25c199b5.jpg","/api/assets/images/1771169405444-1501e4db873cda5cee67430250c06d16.jpg","/api/assets/images/1771169407242-ee9483b051a066d225a6925ce9ac244c.jpg","/api/assets/images/1771169409184-photo_mid_def_1016258_390x.jpg","/api/assets/images/1771169412781-versace-mules.webp"],"image_url":"/api/assets/images/1771169285915-VERSACE-FALL-1991-RTW-04-CINDY-CRAWFORD.webp","caption":"Versace builds a new kind of Italian glamour: classical references and graphic motifs pushed through body conscious tailoring, metalwork, and unapologetic sex appeal. The house becomes a runway to pop culture engine, defining the supermodel era in the process.\n"},{"title":"Donatella years: Runway","year_range":"1997 - 2018","description":"On the runway, Donatella evolves Versace from Gianni’s baroque provocation into a sharper, more “camera-ready” house language: glossy tailoring, weaponized sex appeal, and instantly legible codes (Medusa, Greca, Barocco) built for modern fashion media cycles.","images":["/api/assets/images/1771169689593-100010037.webp","/api/assets/images/1771169693527-versace-spring-2000-ready-to-wear-v0-zrzjtghs1a0e1.jpg","/api/assets/images/1771169698491-versace_900x.webp","/api/assets/images/1771169700546-tumblr_45559e6bb9f4e3c1f69348fbf19eef24_490bb5b1_1280.jpg","/api/assets/images/1771169702316-versace-spring-2004-couture-00010h-karolina-kurkova.webp","/api/assets/images/1771169704961-versace-spring-2004-couture-00060h-christina-kruse.webp","/api/assets/images/1771169746523-versace-spring-2004-couture-00050h-marija-vujovic.webp","/api/assets/images/1771169748402-versace-spring-2004-couture-00080h-daria-werbowy.webp","/api/assets/images/1771169750855-versace-spring-2004-couture-00170h-christina-kruse.webp"],"image_url":"/api/assets/images/1771169689593-100010037.webp","caption":"On the runway, Donatella evolves Versace from Gianni’s baroque provocation into a sharper, more “camera-ready” house language: glossy tailoring, weaponized sex appeal, and instantly legible codes (Medusa, Greca, Barocco) built for modern fashion media cycles."},{"title":"Donatella years: Red Carpet","year_range":"2018 - 2025","description":"In celebrity dressing, Donatella turns Versace into a culture machine: a red carpet and stage uniform that signals power, sex, and spectacle in a single frame. \nThe clothes are engineered to be remembered- high slit, high shine, high recognition.","images":["/api/assets/images/1771170363499-GettyImages-2279421.webp","/api/assets/images/1771170366810-GettyImages-1867743.webp","/api/assets/images/1771170374048-GettyImages-75867957.webp","/api/assets/images/1771170376835-GettyImages-73421595.webp","/api/assets/images/1771170379157-GettyImages-76450826.webp","/api/assets/images/1771170381510-GettyImages-106686701.webp","/api/assets/images/1771170385922-GettyImages-140071094.webp","/api/assets/images/1771170388283-GettyImages-955803654.webp","/api/assets/images/1771170393064-GettyImages-1395090108.webp","/api/assets/images/1771170396101-GettyImages-1395055863.webp","/api/assets/images/1771170398343-GettyImages-1147433066.webp","/api/assets/images/1771170401647-GettyImages-1395030039.webp"],"image_url":"/api/assets/images/1771170363499-GettyImages-2279421.webp","caption":"In celebrity dressing, Donatella turns Versace into a culture machine: a red carpet and stage uniform that signals power, sex, and spectacle in a single frame. \nThe clothes are engineered to be remembered- high slit, high shine, high recognition."},{"title":"Dario Short Era","year_range":"2025","description":"Vitale’s short tenure reads like a transition capsule: Versace begins testing a cleaner, more editorial design language while still needing to “speak Versace” through recognizable codes. It’s a reset attempt framed by ownership change and rapid succession.","images":["/api/assets/images/1771170534012-1080.avif","/api/assets/images/1771170536129-4b80.avif","/api/assets/images/1771170538125-versace-ss26-first-press-look-67.jpg","/api/assets/images/1771170540123-VERSACE-SS26-VOGUE-Look-12.webp","/api/assets/images/1771170542905-VERSACE-STORY.webp"],"image_url":"/api/assets/images/1771170534012-1080.avif","caption":"Vitale’s short tenure reads like a transition capsule: Versace begins testing a cleaner, more editorial design language while still needing to “speak Versace” through recognizable codes. It’s a reset attempt framed by ownership change and rapid succession."}]','[{"name":"Printed Georgette Top","image_url":"/api/assets/images/1771170664186-P01129286.avif","link":"https://www.mytheresa.com/euro/en/women/versace-printed-georgette-top-pink-p01129286"},{"name":"La Medusa Satin Bag","image_url":"/api/assets/images/1771170718490-P01157367.avif","link":"https://www.mytheresa.com/euro/en/women/versace-la-medusa-mini-satin-top-handle-bag-black-p01157367"},{"name":"Medusa ''95 Draped Gown","image_url":"/api/assets/images/1771170741500-P01129220.avif","link":"https://www.mytheresa.com/euro/en/women/versace-medusa-95-draped-jersey-gown-gold-p01129220"},{"name":"Virgin Wool Blazer","image_url":"/api/assets/images/1771170762994-P01129280.avif","link":"https://www.mytheresa.com/euro/en/women/versace-virgin-wool-blazer-white-p01129280"},{"name":"Gianni Ribbon 85 Pumps","image_url":"/api/assets/images/1771171113317-P01131083.avif","link":"https://www.mytheresa.com/euro/en/women/versace-gianni-ribbon-85-leather-slingback-pumps-white-p01131083"}]','2026-02-15 15:58:38','2026-02-15 15:58:38');
INSERT INTO "designers" VALUES(7,'Bottega Veneta','bottega-veneta','boh-TEH-gah veh-NAY-tah','/api/assets/audio/1771176152383-Bottega_Veneta.mp3','The house says Bottega Veneta means “Venetian artisanal workshop”, a name that emphasizes collective craft over a single founder’s surname.','/api/assets/images/1771176194829-BV_S24_Adv_sRGB_16x9_imageonly_B12.jpg','Michele Taddei & Renzo Zengiaro','1966','Vicenza, Veneto, Italy','Louise Trotter','[{"name":"Heritage","description":""},{"name":"Artisanal","description":""},{"name":"Minimalist","description":""},{"name":"Luxury","description":""}]','[{"title":"The Vicenza Workshop & Quiet Luxury","year_range":"1966 - 2000","description":"Bottega builds a reputation on discretion: leather craft becomes the “logo,” and the house’s identity coheres around intrecciato weaving and an anti-monogram attitude that reads as quietly elite long before “quiet luxury” becomes a headline.","images":["/api/assets/images/1771269702459-MMDAMGI_EC004_copy.webp","/api/assets/images/1771269705902-diana-princess-of-wales.avif","/api/assets/images/1771269708267-tina-turner-during-tina.avif","/api/assets/images/1771269710685-new-york-city-july.avif","/api/assets/images/1771269714108-MADONNA_KNOT_1991.webp","/api/assets/images/1771269716507-380629-05-exclusive-actress.avif"],"image_url":"/api/assets/images/1771269702459-MMDAMGI_EC004_copy.webp","caption":"Bottega builds a reputation on discretion: leather craft becomes the “logo,” and the house’s identity coheres around intrecciato weaving and an anti-monogram attitude that reads as quietly elite long before “quiet luxury” becomes a headline."},{"title":"Tomas Maier’s Modern House Rebuild","year_range":"2001 - 2018","description":"Under Tomas Maier, Bottega turns craft into a full wardrobe proposition: expanding from accessories into a broader luxury universe while keeping the house’s restraint intact. The message is consistency: modern, tactile, and made to last.","images":["/api/assets/images/1771270216285-00010fullscreen.webp","/api/assets/images/1771270219859-00100fullscreen.webp","/api/assets/images/1771270222121-00310fullscreen.webp","/api/assets/images/1771270224569-00310fullscreen_1_.webp","/api/assets/images/1771270226467-00380fullscreen.webp","/api/assets/images/1771270230101-00430fullscreen.webp","/api/assets/images/1771270232276-00010fullscreen_1_.webp","/api/assets/images/1771270235377-00050fullscreen.webp","/api/assets/images/1771270238926-00450m.webp","/api/assets/images/1771270242803-00010m.webp"],"image_url":"/api/assets/images/1771270216285-00010fullscreen.webp","caption":"Under Tomas Maier, Bottega turns craft into a full wardrobe proposition: expanding from accessories into a broader luxury universe while keeping the house’s restraint intact. The message is consistency: modern, tactile, and made to last."},{"title":"Daniel Lee’s “New Bottega” Heat","year_range":"2018 - 2021","description":"Lee sharpens Bottega into a culture engine: bold proportions, amplified intrecciato, and accessories designed to move fast in street style without leaning on overt logos. The house feels younger, punchier, and instantly memetic.","images":["/api/assets/images/1771270474016-PF19_28_W_WEB_UC734916.jpg","/api/assets/images/1771270478572-PF19_33_W_WEB_UC734921.jpg","/api/assets/images/1771270489706-PF19_36_W_WEB_UC734924.jpg","/api/assets/images/1771270492132-PF19_32_W_WEB_UC734920.jpg","/api/assets/images/1771270502843-395239.jpg","/api/assets/images/1771270505674-05_200222_Serichai_BottegaVenetta-046.avif","/api/assets/images/1771270511141-395242.avif","/api/assets/images/1771270517500-07_200222_Serichai_BottegaVenetta-027.avif","/api/assets/images/1771270521293-395246.avif"],"image_url":"/api/assets/images/1771270474016-PF19_28_W_WEB_UC734916.jpg","caption":"Lee sharpens Bottega into a culture engine: bold proportions, amplified intrecciato, and accessories designed to move fast in street style without leaning on overt logos. The house feels younger, punchier, and instantly memetic."},{"title":"Blazy to Trotter","year_range":"2022 - present","description":"Bottega doubles down on material intelligence under Matthieu Blazy, elevating illusion, handwork, and tactile precision into a defining language. In 2025, Louise Trotter arrives from Carven & Lacoste, refining that foundation with pragmatic tailoring and lived-in restraint, reasserting the house’s quiet authority through clarity rather than spectacle.","images":["/api/assets/images/1771270967201-418660.avif","/api/assets/images/1771270969288-451825.avif","/api/assets/images/1771270971408-220228044206-04-bottega-veneta-winter-2022.jpg","/api/assets/images/1771270974552-gettyimages-1238786152-675b297784a6f.avif","/api/assets/images/1771270977631-bottega-veneta-f24-065-65db5ad465585.avif","/api/assets/images/1771270979903-bottega-veneta-fashion-week-milan-matthieu-blazy-2-scaled.jpg","/api/assets/images/1771270993781-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_02_bottega-veneta-matthieu-blazy-first-show-fw22-mfw-images-47.avif","/api/assets/images/1771270996524-winter2024-look-19-w-fio00332-1708944184201.jpg","/api/assets/images/1771271099997-67754997530b53ecd62f3258099ae30f.avif","/api/assets/images/1771271106505-Bottega_Veneta_SS26_Womenswear_045.width-640_ae7X6uBMjYeyrIxH.jpg","/api/assets/images/1771271108668-defile-bottega-veneta-printemps-ete-2026-fashion-week-milan-louise-trotter13.jpg","/api/assets/images/1771271110803-FIO00819_1_.webp","/api/assets/images/1771271128893-FIO00041.webp","/api/assets/images/1771271130946-FIO01255.webp"],"image_url":"/api/assets/images/1771270967201-418660.avif","caption":"Bottega doubles down on material intelligence under Matthieu Blazy, elevating illusion, handwork, and tactile precision into a defining language. In 2025, Louise Trotter arrives from Carven & Lacoste, refining that foundation with pragmatic tailoring and lived-in restraint, reasserting the house’s quiet authority through clarity rather than spectacle."}]','[{"name":"Barbara Tote Bag","image_url":"/api/assets/images/1771176452121-P01151260.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-barbara-intrecciato-small-leather-tote-bag-black-p01151260"},{"name":"Intrecciato 75 Ankle Boots","image_url":"/api/assets/images/1771176476086-P01099523.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-atomic-intrecciato-50-leather-and-suede-ankle-boots-brown-p01099523"},{"name":"Intrecciato Trench Coat","image_url":"/api/assets/images/1771176497203-P01141982.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-leather-trimmed-cotton-blend-trench-coat-green-p01141982"},{"name":"Andiamo Intrecciato Tote Bag","image_url":"/api/assets/images/1771176523177-P01117827.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-andiamo-intrecciato-large-leather-tote-bag-green-p01117827"},{"name":"Knot Leather Clutch","image_url":"/api/assets/images/1771176546595-P01118351.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-knot-mini-embellished-suede-clutch-gold-p01118351"},{"name":"Astaire Knot Mules","image_url":"/api/assets/images/1771176573082-P01126437.avif","link":"https://www.mytheresa.com/int/en/women/bottega-veneta-astaire-knot-leather-mules-brown-p01126437"}]','2026-02-15 17:29:38','2026-02-16 19:45:35');
INSERT INTO "designers" VALUES(8,'Schiaparelli','schiaparelli','skee-AP-uh-REL-ee','/api/assets/audio/1771271372250-Schiaparelli.mp3','The house is named for founder Elsa Schiaparelli, an Italian surname that became shorthand for her Paris-era, Surrealism-linked couture universe.','/api/assets/images/1771271375082-Dizajn-bez-nazvaniya-45-1.png','Elsa Schiaparelli','1927','Paris, France','Daniel Roseberry','[{"name":"Avant-garde","description":""},{"name":"Couture","description":""},{"name":"Sculptural","description":""},{"name":"Conceptual","description":""}]','[{"title":"Elsa’s Modernist Surrealist Foundation","year_range":"1927 - 1939","description":"Schiaparelli establishes couture as an intellectual and artistic practice rather than a decorative one. Elsa fuses modernist experimentation with Surrealist collaboration, transforming garments into witty, symbolic objects. Trompe-l’œil knits, shocking pink, and illusion based couture redefine what fashion can communicate,\npositioning the house as Paris’s most conceptually daring atelier.","images":["/api/assets/images/1771272577179-960.jpg","/api/assets/images/1771272578980-551f9ab35fd721ad88dd474067a5b617.jpg","/api/assets/images/1771272581001-1-2-724x1024.jpg","/api/assets/images/1771272583420-blouse-1950-schiaparelli.jpg","/api/assets/images/1771272585229-Elsa-Schiaparelli-3.jpg","/api/assets/images/1771272588616-les-artistes-51-dali-img_2x_9a0776f3-9b3e-425d-a8df-6e81a6abb885.webp","/api/assets/images/1771272638510-c78d3948d248619b78991b6897678ecd.jpg","/api/assets/images/1771272641064-elsa-schiaparelli-3.webp"],"image_url":"/api/assets/images/1771272577179-960.jpg","caption":"Schiaparelli establishes couture as an intellectual and artistic practice rather than a decorative one. Elsa fuses modernist experimentation with Surrealist collaboration, transforming garments into witty, symbolic objects. Trompe-l’œil knits, shocking pink, and illusion based couture redefine what fashion can communicate,\npositioning the house as Paris’s most conceptually daring atelier."},{"title":"War, Recalibration, and Closure","year_range":"1940 - 1954","description":"World War II disrupts Paris couture and fractures the house’s momentum. After relocating and later returning to a changed postwar landscape, Schiaparelli attempts to recalibrate amid shifting tastes that favor softer romanticism. The maison closes in 1954, but its visual language: anatomy, symbolism, audacity, remains embedded in fashion history.","images":["/api/assets/images/1771272941006-tumblr_o6220v7mF41tzpr0yo1_1280.jpg","/api/assets/images/1771272945309-Joan-Crawford-1932-photo-by-Edward-Steichen-1932.webp","/api/assets/images/1771272947494-bd255218d2e66cce3608dc69795eee90.jpg","/api/assets/images/1771272950117-85212720cf1189b63e7eb191c689b6e8.jpg","/api/assets/images/1771272953327-7786b0d595a7c46ff817376e3273ec00.jpg","/api/assets/images/1771272957078-755bdf518c79b340c6d6c70c1d516fd7.jpg","/api/assets/images/1771272960208-wallis-simspon-schiaparelli-lobster-dress-beaton-19370601-CN00019279.jpg","/api/assets/images/1771272962591-vogue-1951-photo-henry-clarke-schiaparelli.jpeg"],"image_url":"/api/assets/images/1771272941006-tumblr_o6220v7mF41tzpr0yo1_1280.jpg","caption":"World War II disrupts Paris couture and fractures the house’s momentum. After relocating and later returning to a changed postwar landscape, Schiaparelli attempts to recalibrate amid shifting tastes that favor softer romanticism. The maison closes in 1954, but its visual language: anatomy, symbolism, audacity, remains embedded in fashion history."},{"title":"Dormancy and Legacy","year_range":"1955 - 2006 ","description":"Though inactive as a functioning couture house, Schiaparelli evolves into a mythic reference point. Museums, exhibitions, and designers revisit Elsa’s Surrealist codes, preserving the brand in cultural memory. During these decades, Schiaparelli exists less as a business and more as an intellectual blueprint for avant-garde fashion.","images":["/api/assets/images/1771273274348-Image01.width-2880_AciEXcHg9bapiElv.jpg","/api/assets/images/1771273276464-774292-shocking-les-mondes-surrealistes-d-elsa-schiaparelli-nos-photos-de-l-exposition-mode-au-mad.jpg","/api/assets/images/1771273279950-774316-shocking-les-mondes-surrealistes-d-elsa-schiaparelli-nos-photos-de-l-exposition-mode-au-mad.jpg","/api/assets/images/1771273282800-3b99b02118a733df57160edf5be97ad6.jpg","/api/assets/images/1771273285040-sqbNhTj43wASaTKmuXQq2eUP1cKBTiK2dX1LQHJb.jpg","/api/assets/images/1771273289165-Dali_Schiaparelli-7.webp","/api/assets/images/1771273293860-Dali_Schiaparelli-9.webp","/api/assets/images/1771273295853-Dali_Schiaparelli-20.webp","/api/assets/images/1771273299595-Dali_Schiaparelli-27.webp"],"image_url":"/api/assets/images/1771273274348-Image01.width-2880_AciEXcHg9bapiElv.jpg","caption":"Though inactive as a functioning couture house, Schiaparelli evolves into a mythic reference point. Museums, exhibitions, and designers revisit Elsa’s Surrealist codes, preserving the brand in cultural memory. During these decades, Schiaparelli exists less as a business and more as an intellectual blueprint for avant-garde fashion."},{"title":"Revival and Rebuilding at Place Vendôme","year_range":"2007 - 2018","description":"The house reawakens under new ownership with the aim of restoring couture legitimacy rather than launching a trend-driven label. Reopened at 21 Place Vendôme, Schiaparelli tests its modern identity through successive creative directors and couture presentations, gradually reclaiming its official haute couture status and reestablishing itself within Paris’s heritage ecosystem.","images":["/api/assets/images/1771359268127-_ARC0006.1366x2048.webp","/api/assets/images/1771359270070-_ARC0042.1366x2048.webp","/api/assets/images/1771359271974-_ARC0111.1366x2048.webp","/api/assets/images/1771359274138-_ARC0137.1366x2048.webp","/api/assets/images/1771359276351-KIM_2170.webp","/api/assets/images/1771359280576-KIM_2190.webp","/api/assets/images/1771359282650-KIM_2334.webp","/api/assets/images/1771359285082-SCH_0140.1366x2048.webp","/api/assets/images/1771359286887-SCH_0317.1366x2048.webp","/api/assets/images/1771359291374-SCH_0412.1366x2048.webp","/api/assets/images/1771359293539-KIM_0032.webp","/api/assets/images/1771359295992-KIM_0079.webp"],"image_url":"/api/assets/images/1771359268127-_ARC0006.1366x2048.webp","caption":"The house reawakens under new ownership with the aim of restoring couture legitimacy rather than launching a trend-driven label. Reopened at 21 Place Vendôme, Schiaparelli tests its modern identity through successive creative directors and couture presentations, gradually reclaiming its official haute couture status and reestablishing itself within Paris’s heritage ecosystem."},{"title":"Daniel Roseberry and the Image-Era Renaissance","year_range":"2019 - Present","description":"Under Daniel Roseberry, Schiaparelli reasserts itself as a contemporary cultural force. Couture becomes sculptural, hyper-symbolic, and engineered for global visibility, anatomical gold hardware, exaggerated tailoring, and mythic motifs designed for red carpets and digital circulation. The house shifts from archival reverence to present tense relevance, translating Elsa’s surreal audacity into modern spectacle.","images":["/api/assets/images/1771359592274-00001-Schiaparelli-Couture-Fall-21-credit-Daniel-Roseberry-brand.webp","/api/assets/images/1771359594484-00004-Schiaparelli-Couture-Fall-21-credit-Daniel-Roseberry-brand.webp","/api/assets/images/1771359596535-00006-Schiaparelli-Couture-Fall-21-credit-Daniel-Roseberry-brand.webp","/api/assets/images/1771359598632-00015-Schiaparelli-Couture-Fall-21-credit-Daniel-Roseberry-brand.webp","/api/assets/images/1771359608297-00002-Schiaparelli-Couture-Spring-22-credit-Gorunway.webp","/api/assets/images/1771359614678-00004-schiaparelli-spring-2023-couture-gorunway.webp","/api/assets/images/1771359618396-00005-Schiaparelli-Couture-Spring-22-credit-Gorunway.webp","/api/assets/images/1771359620251-00005-schiaparelli-spring-2023-couture-gorunway.webp","/api/assets/images/1771359622876-00009-Schiaparelli-Couture-Spring-22-credit-Gorunway.webp","/api/assets/images/1771359624725-00015-Schiaparelli-Couture-Spring-22-credit-Gorunway.webp","/api/assets/images/1771359626668-00017-schiaparelli-fall-2023-couture-credit-gorunway.webp","/api/assets/images/1771359632660-00023-schiaparelli-fall-2023-couture-credit-gorunway.webp","/api/assets/images/1771359634939-00023-schiaparelli-spring-2023-couture-gorunway.webp","/api/assets/images/1771359637608-00030-schiaparelli-spring-2023-couture-gorunway.webp"],"image_url":"/api/assets/images/1771359592274-00001-Schiaparelli-Couture-Fall-21-credit-Daniel-Roseberry-brand.webp","caption":"Under Daniel Roseberry, Schiaparelli reasserts itself as a contemporary cultural force. Couture becomes sculptural, hyper-symbolic, and engineered for global visibility, anatomical gold hardware, exaggerated tailoring, and mythic motifs designed for red carpets and digital circulation. The house shifts from archival reverence to present tense relevance, translating Elsa’s surreal audacity into modern spectacle."}]','[{"name":"BASQUE JACKET","image_url":"/api/assets/images/1771360596445-packshot_S1WGW2S6JA0002PI3410_999.webp","link":"https://schiaparelli.com/en/collections/pret-a-porter/products/s1wgw2s6ja0002pi3410999"},{"name":"FACE BAG","image_url":"/api/assets/images/1771360623999-packshot_SA159180_001.webp","link":"https://schiaparelli.com/en/collections/sacs/products/sa159180001"},{"name":"TROMPE L''OEIL JUMPER","image_url":"/api/assets/images/1771360643252-packshot_S1WGK2S6SW0005600000_999.webp","link":"https://schiaparelli.com/en/collections/maille/products/s1wgk2s6sw0005600000999"},{"name":"KEYHOLE BIJOUX CHAIN CLUTCH","image_url":"/api/assets/images/1771360659091-packshot_PM109044_999.webp","link":"https://schiaparelli.com/en/collections/sacs/products/pm109044999"},{"name":"ZIP-UP SWEATSHIRT","image_url":"/api/assets/images/1771360681896-packshot_SW70036000_107.webp","link":"https://schiaparelli.com/en/collections/maille/products/sw70036000107"},{"name":"MOLDED MOUTH CHAIN CLUTCH","image_url":"/api/assets/images/1771360699217-packshot_S1WLL2S6SL0027CA9129_004.webp","link":"https://schiaparelli.com/en/collections/sacs/products/s1wll2s6sl0027ca9129004"}]','2026-02-16 20:21:45','2026-02-17 20:38:23');
INSERT INTO "designers" VALUES(9,'Alaïa','ala-a','ah-LIE-ah','/api/assets/audio/1771360957373-Alai_a.mp3','An eponymous house named for its founder, Tunisian-French couturier Azzedine Alaïa; the diaeresis (ï) signals the two vowels are pronounced separately (“a-ï-a”).','/api/assets/images/1771361036844-ALAIA-SUMMER-FALL-2025-AD-CAMPAIGN.jpg','Azzedine Alaïa','1979','Paris, France','Pieter Mulier','[{"name":"Sculptural","description":""},{"name":"Tailoring","description":""},{"name":"Artisanal","description":""},{"name":"Refined","description":""}]','[{"title":"Atelier “Second Skin” Cult","year_range":"1979 - 1986","description":"Alaïa builds the house from an intimate Paris atelier practice: fitting, cutting, and refining garments like sculpture, until the clothes read as engineered “second skin\". The identity is set: sensual precision, not seasonal spectacle.","images":["/api/assets/images/1771528856776-FA00017197_00028_Enhanced.webp","/api/assets/images/1771528858834-FA00017197_00036_Enhanced.webp","/api/assets/images/1771528860711-FA00017197_00100_Enhanced.webp","/api/assets/images/1771528862589-FA00017197_00140_Enhanced.webp","/api/assets/images/1771528864646-FA00017197_00166_Enhanced.webp","/api/assets/images/1771528866730-FA00017197_00173_Enhanced.webp","/api/assets/images/1771528868607-0a84f5ffbc1fdd346b725d252502c489.jpg","/api/assets/images/1771528872925-b7ee394276f315ea2fe72d50918a55d2.jpg"],"image_url":"/api/assets/images/1771528856776-FA00017197_00028_Enhanced.webp","caption":"Alaïa builds the house from an intimate Paris atelier practice: fitting, cutting, and refining garments like sculpture, until the clothes read as engineered “second skin\". The identity is set: sensual precision, not seasonal spectacle."},{"title":"Global Power Years","year_range":"1987 - 1997","description":"The house translates its body conscious mastery into a globally legible silhouette language: clean lines, commanding shoulders, curve-tracing knits, while proving that technical rigor can still feel intimate. Alaïa’s independence becomes part of the brand’s aura.","images":["/api/assets/images/1771529119282-s-l400.jpg","/api/assets/images/1771529121451-naomi-campbell-in-azzedine-alaia-fall-1991-guy-marineau.jpg","/api/assets/images/1771529123460-AZZEDINE-ALAIA-FALL-1991-RTW-105-ELLE-MACPHERSON.webp","/api/assets/images/1771529125470-AZZEDINE-ALAIA-FALL-1991-RTW-06-CLAUDIA-SCHIFFER.webp","/api/assets/images/1771529127329-43370e0f26fbd781cf1c082e67173774.jpg","/api/assets/images/1771529129547-8641daf11e9ea9df3616138774166173.jpg","/api/assets/images/1771529133137-11_Christy_Turlington_in_Chez_Azzedine_Alaia_French_Elle_May_18_1992_._Photographed_by_Gilles_Bensimon_900x.webp","/api/assets/images/1771529134965-5fd76a758872d353bd4e0255728773de.jpg"],"image_url":"/api/assets/images/1771529119282-s-l400.jpg","caption":"The house translates its body conscious mastery into a globally legible silhouette language: clean lines, commanding shoulders, curve-tracing knits, while proving that technical rigor can still feel intimate. Alaïa’s independence becomes part of the brand’s aura."},{"title":"Independent Rhythm & Archive Authority","year_range":"1998 - 2017","description":"Alaïa doubles down on refusing the fashion week tempo, using time as a design tool: fewer shows, deeper development, and a house language anchored in cut, knit, and artisanal finish. His death in 2017 closes the founder era and crystallizes the brand’s authority in permanence over novelty.","images":["/api/assets/images/1771529341180-alaia-fashion-08.webp","/api/assets/images/1771529342931-alaia-fashion-09.webp","/api/assets/images/1771529345202-alaia-fashion-10.webp","/api/assets/images/1771529347221-alaia-fashion-11.webp","/api/assets/images/1771529348847-alaia-fashion-14.webp","/api/assets/images/1771529351314-alaia-fashion-15.webp","/api/assets/images/1771529353359-alaia-fashion-16.webp","/api/assets/images/1771529357852-alaia-fashion-17.webp","/api/assets/images/1771529359592-alaia-fashion-18.webp","/api/assets/images/1771529361314-alaia-fashion-20.webp"],"image_url":"/api/assets/images/1771529341180-alaia-fashion-08.webp","caption":"Alaïa doubles down on refusing the fashion week tempo, using time as a design tool: fewer shows, deeper development, and a house language anchored in cut, knit, and artisanal finish. His death in 2017 closes the founder era and crystallizes the brand’s authority in permanence over novelty."},{"title":"Pieter Mulier Revival & Accessories Breakout","year_range":"2021 - 2026","description":"Mulier modernizes Alaïa by sharpening its architectural instincts, turning “second skin” into clean, graphic, often modular constructions, while finally giving the house breakout accessories that feel as engineered as the clothes. Craft remains the headline; visibility scales.","images":["/api/assets/images/1771529561757-00001-alaia-spring-2026-ready-to-wear-credit-brand.webp","/api/assets/images/1771529563752-00003-Alaia-Fall-22-Paris-credit-brand.webp","/api/assets/images/1771529565955-00006-Alaia-Spring-22-credit-brand.webp","/api/assets/images/1771529567700-ALAIA_SS22_LOOKBOOK_039.width-640_DEuORujuJMqLZpFv.jpg","/api/assets/images/1771529569723-alaia-fall-25-rtw-r-ho-005.webp","/api/assets/images/1771529572172-00001-alaia-fall-2024-ready-to-wear-credit-brand.webp","/api/assets/images/1771529576917-alaia-sf24-look-front-15-65b13121b6ad4.avif","/api/assets/images/1771529580919-alaia-summer-fall-2024-38.jpg","/api/assets/images/1771529584911-Alaia2.png","/api/assets/images/1771529587457-alaiasf24lookfront43-cea54944.webp","/api/assets/images/1771529590455-alaiasf25lookfront12-9428abc5.webp","/api/assets/images/1771529593099-https_hypebeast.com_image_2025_03_05_alaia-fall-winter-2025-runway-collection-32.avif","/api/assets/images/1771529598876-alaia-ws25-look-front_39.avif","/api/assets/images/1771529600885-alaia-ws25-look-front-19-66dc7e48b8dad.avif"],"image_url":"/api/assets/images/1771529561757-00001-alaia-spring-2026-ready-to-wear-credit-brand.webp","caption":"Mulier modernizes Alaïa by sharpening its architectural instincts, turning “second skin” into clean, graphic, often modular constructions, while finally giving the house breakout accessories that feel as engineered as the clothes. Craft remains the headline; visibility scales."}]','[{"name":"Le Click East West Bag","image_url":"/api/assets/images/1771529737653-P01115343.avif","link":"https://www.mytheresa.com/int/en/women/alaia-le-click-east-west-medium-shoulder-bag-grey-p01115343"},{"name":"Open Knit Wool Midi Skirt","image_url":"/api/assets/images/1771529763049-P01118822.avif","link":"https://www.mytheresa.com/int/en/women/alaia-open-knit-wool-blend-midi-skirt-black-p01118822"},{"name":"Faded Barrel Leg Jeans","image_url":"/api/assets/images/1771529786786-P01118587.avif","link":"https://www.mytheresa.com/int/en/women/alaia-faded-barrel-leg-jeans-blue-p01118587"},{"name":"Mina 20 New Vienne Bag","image_url":"/api/assets/images/1771529826781-P01115356.avif","link":"https://www.mytheresa.com/int/en/women/alaia-mina-20-new-vienne-leather-tote-bag-brown-p01115356"},{"name":"Peplum Bomber Jacket","image_url":"/api/assets/images/1771529843570-P01118698.avif","link":"https://www.mytheresa.com/int/en/women/alaia-peplum-bomber-jacket-black-p01118698"},{"name":"Jersey Bodysuit","image_url":"/api/assets/images/1771529804114-P01112290.webp","link":"https://www.mytheresa.com/int/en/women/alaia-jersey-bodysuit-black-p01112290"}]','2026-02-17 20:45:39','2026-02-19 19:37:27');
INSERT INTO "designers" VALUES(10,'Fendi','fendi','FEHN-dee','/api/assets/audio/1771529982232-Fendi.mp3','“Fendi” is the founders’ family surname (Adele Casagrande Fendi and Edoardo Fendi), used as the house name from its beginnings in Rome.','/api/assets/images/1771530089763-FENDI-FALL-2025-CAMPAIGN-FILM.jpg','Adele Casagrande Fendi & Edoardo Fendi','1925','Rome, Italy','Maria Grazia Chiuri','[{"name":"Luxury","description":""},{"name":"Heritage","description":""},{"name":"Artisanal","description":""},{"name":"Logo-centric","description":""}]','[{"title":"Roman Fur & Leather Origins","year_range":"1925 - 1964","description":"Fendi builds its identity as a Roman atelier rooted in fur and leather goods, growing from a local workshop into a name associated with meticulous handwork and “made-in-Rome” polish, before the house becomes a modern fashion system.","images":["/api/assets/images/1771530610201-63d7d231b31e3e63c49c19d48f8836ff.jpg","/api/assets/images/1771530612145-8632_orig.jpg","/api/assets/images/1771530614285-d8c55203b52d5d93fbbb5dcb8c061916.jpg","/api/assets/images/1771530616434-fendi-1966.jpg","/api/assets/images/1771530618363-fendi-archive-3.webp","/api/assets/images/1771530620049-fendi01.webp","/api/assets/images/1771530623355-fendi02.webp"],"image_url":"/api/assets/images/1771530610201-63d7d231b31e3e63c49c19d48f8836ff.jpg","caption":"Fendi builds its identity as a Roman atelier rooted in fur and leather goods, growing from a local workshop into a name associated with meticulous handwork and “made-in-Rome” polish, before the house becomes a modern fashion system."},{"title":"Lagerfeld Modernizes the Codes","year_range":"1965 - 1996","description":"With Karl Lagerfeld, Fendi turns heritage into a graphic, forward facing language making fur lighter, sharper, and more fashion driven while establishing house codes that can travel from ateliers to global retail without losing Roman bite.","images":["/api/assets/images/1771531036965-karl-lagerfeld-fendi-special-issue-2.webp","/api/assets/images/1771531044082-bc155460cc1e6ed199291880db280250.jpg","/api/assets/images/1771531048501-99b9b3bef2f74fc12c41f843dc3ecb10.jpg","/api/assets/images/1771531050863-95f8b3305b11d5cc9b9b6d312dbcae07.jpg","/api/assets/images/1771531055402-tyra-banks-for-fendi-fall-1990-ready-to-wear-runway-show-v0-wmgz0hskxyke1.webp","/api/assets/images/1771531057681-7610839fe84a8ed2ddc2d64b3c927454.jpg","/api/assets/images/1771531060233-5715a0ed743e384662e996d7ccc7edba.jpg","/api/assets/images/1771531063231-842e431b7d4f79448afab16a1aae7720.jpg","/api/assets/images/1771531066844-27db1996e4ba1bee727f98a89a4b1ad8.jpg","/api/assets/images/1771531068884-9ee2ec052accdd7c0da3b8c70c60641f.jpg"],"image_url":"/api/assets/images/1771531036965-karl-lagerfeld-fendi-special-issue-2.webp","caption":"With Karl Lagerfeld, Fendi turns heritage into a graphic, forward facing language making fur lighter, sharper, and more fashion driven while establishing house codes that can travel from ateliers to global retail without losing Roman bite."},{"title":"The Accessories Empire & It-Bag Culture","year_range":"1997 - 2018","description":"Fendi becomes a leather goods powerhouse: accessories shift from supporting act to cultural engine, with the house mastering the loop between runway, celebrity, and product icon, without dropping its craft-first standards.","images":["/api/assets/images/1771531726826-fdjfdif_1946x.webp","/api/assets/images/1771531728672-10848000.webp","/api/assets/images/1771531731065-original_1_.webp","/api/assets/images/1771531734414-Hollywood.jpg","/api/assets/images/1771531741492-_methode_sundaytimes_prod_web_bin_99c1f5be-af39-11e7-834d-7c855d71f8ea.jpg","/api/assets/images/1771531744097-_methode_sundaytimes_prod_web_bin_9f186afc-af39-11e7-834d-7c855d71f8ea.jpg","/api/assets/images/1771531848446-1644321120-1604949036421541-10-fendi-peekaboo-campaign-backstage-images-copie.avif","/api/assets/images/1771531851269-kardashians-fendi-peekaboo-bag-ad-campaign-1.jpg","/api/assets/images/1771531853026-Naomi_Fendi1-480x600.jpg","/api/assets/images/1771531854657-Fendi-Naomi-Watts-Feature.jpg"],"image_url":"/api/assets/images/1771531726826-fdjfdif_1946x.webp","caption":"Fendi becomes a leather goods powerhouse: accessories shift from supporting act to cultural engine, with the house mastering the loop between runway, celebrity, and product icon, without dropping its craft-first standards."},{"title":"Post Karl Transitions, Couture Spectacle","year_range":"2019 - present","description":"After Lagerfeld’s long reign, Fendi balances continuity and reset, leaning into Roman spectacle and category strength while rethinking who authors the full silhouette. The current chapter tightens the house’s creative direction under a clear lead to sharpen the brand’s next century.","images":["/api/assets/images/1771532292775-fendi-rtw-fall-2020-gg-002.webp","/api/assets/images/1771532294656-Fendi-Fashion-Show-SS-2020.jpg","/api/assets/images/1771532297737-Fendi-Fall-Winter-2024-2025-Runway-Magazine-51.webp","/api/assets/images/1771532301677-fendi-ss20-0017-b6bff2.webp","/api/assets/images/1771532303649-gettyimages-1175699206.avif","/api/assets/images/1771532308244-GettyImages-1341863086.webp","/api/assets/images/1771532310001-fendi-fall-2021-collection-review-1.jpg","/api/assets/images/1771532311792-Fendi-couture-SS21-photos-019.webp","/api/assets/images/1771532318266-00003-Fendi-Couture-Spring-21.webp","/api/assets/images/1771532321383-00003-Fendi-Spring-22-rtw-Milan-credit-gorunway.jpg","/api/assets/images/1771532325266-00002-fendi-spring-2026-ready-to-wear-credit-gorunway.webp","/api/assets/images/1771532328762-abiti-a-righe-larghe-Fendi-SS22-copia.avif","/api/assets/images/1771532334520-gettyimages-2236706737.avif","/api/assets/images/1771532337140-00003-fendi-spring-2026-ready-to-wear-credit-gorunway.webp","/api/assets/images/1771532343853-464446.webp"],"image_url":"/api/assets/images/1771532292775-fendi-rtw-fall-2020-gg-002.webp","caption":"After Lagerfeld’s long reign, Fendi balances continuity and reset, leaning into Roman spectacle and category strength while rethinking who authors the full silhouette. The current chapter tightens the house’s creative direction under a clear lead to sharpen the brand’s next century."}]','[{"name":"Baguette","image_url":"/api/assets/images/1771532677416-8BR600AWQRF1VED_01.jpeg","link":"https://www.fendi.com/ii-en/woman/bags/baguette-mahogany-brown-leather-blooming-crystals-bag-8br600awqrf1ved"},{"name":"Fendi Way Large","image_url":"/api/assets/images/1771532725917-fendi-way-large-bag-8BN369AWPFF1V0H-ajpg.jpeg","link":"https://www.fendi.com/ii-en/woman/bags/fendi-way-large-dove-grey-leather-and-neon-blue-suede-bag-8bn369awpff1v0h"},{"name":"Dark blue Denim Jacket","image_url":"/api/assets/images/1771532763305-FLF849AW82F1UKI_01.avif","link":"https://www.fendi.com/ii-en/woman/ready-to-wear/jacket-dark-blue-ff-denim-blouson-flf849aw82f1uki"},{"name":"","image_url":"","link":""},{"name":"Spy Mini Bag","image_url":"/api/assets/images/1771532796359-8BS110AVU5F1UZD_01.avif","link":"https://www.fendi.com/ii-en/woman/bags/fendi-spy-mini-orange-leather-mini-bag-8bs110avu5f1uzd"},{"name":"Dark Blue Poplin Shirt","image_url":"/api/assets/images/1771532852393-8b0543bedf5da726ac99bdf98c6e7451.webp","link":"https://www.fendi.com/ii-en/woman/new-in/shirt-dark-blue-poplin-shirt-fs8355aw7vf1w0a"}]','2026-02-19 20:27:36','2026-02-19 20:27:36');
INSERT INTO "designers" VALUES(11,'Miu Miu','miu-miu','MYOO MYOO','/api/assets/audio/1771533067161-MIU_MIU.mp3','“Miu Miu” is the childhood nickname of founder Miuccia Prada (born Maria Bianchi). The name signals intimacy and personal expression, positioning the brand as Prada’s more instinctive, experimental counterpart.','/api/assets/images/1771533108855-EmmaMiuMiu4.webp','Miuccia Prada','1993','Milan, Italy','Miuccia Prada','[{"name":"Youthful","description":""},{"name":"Feminine","description":""},{"name":"Experimental","description":""},{"name":"Retro","description":""}]','[{"title":"The Anti Pretty Intellectual","year_range":"","description":"In the 1990s, Miu Miu emerges as Prada’s unruly younger sister: less polished, more instinctive. Miuccia Prada uses awkward color, vintage references, and “ugly-chic” proportions to challenge conventional femininity, cultivating an intellectual cool that quietly reframes what sexy can mean.","images":["/api/assets/images/1771533263285-014-miu-miu-spring-1996-ready-to-wear-CN10055935-kate-moss.webp","/api/assets/images/1771533264961-miumiunux_color.600.600_1_.avif","/api/assets/images/1771533266498-miumiunux_color.600.600.avif","/api/assets/images/1771533268303-miumiunux_color.600.600.jpg","/api/assets/images/1771533307147-001-miu-miu-fall-1999-ready-to-wear-detail-CN10058021-mia-hessner.webp","/api/assets/images/1771533308764-miumiunux_color.600.600_1_.avif","/api/assets/images/1771533310588-miumiunux_color.600.600_2_.avif","/api/assets/images/1771533312440-miumiunux_color.600.600.avif","/api/assets/images/1771533374485-010-miu-miu-fall-2002-ready-to-wear-erin-oconnor.webp","/api/assets/images/1771533376698-016-miu-miu-fall-2002-ready-to-wear-caitriona-balfe.webp","/api/assets/images/1771533378701-023-miu-miu-fall-2002-ready-to-wear-missy-rayder.webp","/api/assets/images/1771533381269-027-miu-miu-fall-2002-ready-to-wear-amanda-moore.webp","/api/assets/images/1771533383754-miumiunux_color.600.600.avif"],"image_url":"/api/assets/images/1771533263285-014-miu-miu-spring-1996-ready-to-wear-CN10055935-kate-moss.webp","caption":"In the 1990s, Miu Miu emerges as Prada’s unruly younger sister: less polished, more instinctive. Miuccia Prada uses awkward color, vintage references, and “ugly-chic” proportions to challenge conventional femininity, cultivating an intellectual cool that quietly reframes what sexy can mean."},{"title":"The Cult-Girl Cinema Era","year_range":"2006–2013","description":"Miu Miu sharpens its identity around art-house femininity and pop eccentricity. The house leans into bold prints, glitter heels, and decorative collars while launching Women’s Tales, aligning the brand with female filmmakers and reinforcing its position as culturally literate yet mischievous.","images":["/api/assets/images/1771533505373-00010fullscreen.webp","/api/assets/images/1771533507225-miu-miu-7.jpg","/api/assets/images/1771533509338-miu-miu-spring-summer-2010-10.webp","/api/assets/images/1771533511102-MiuMiuSS2010_Look15.jpg","/api/assets/images/1771533548907-00020fullscreen.webp","/api/assets/images/1771533551681-b1543f10bf4317f471fd906d52cd67e2.jpg","/api/assets/images/1771533553674-c4770fe2bffda116914edfd4797d481d.jpg","/api/assets/images/1771533604251-00070fullscreen.webp","/api/assets/images/1771533606622-miu-miu-rtw-spring2012-runway-014_110100589436.webp","/api/assets/images/1771533608809-miu-miu01.webp","/api/assets/images/1771533610478-miu-miu13.jpg"],"image_url":"/api/assets/images/1771533505373-00010fullscreen.webp","caption":"Miu Miu sharpens its identity around art-house femininity and pop eccentricity. The house leans into bold prints, glitter heels, and decorative collars while launching Women’s Tales, aligning the brand with female filmmakers and reinforcing its position as culturally literate yet mischievous."},{"title":"The Subversive Youth Reset","year_range":"2014 - 2019","description":"As luxury grows more logo-driven, Miu Miu refocuses on character dressing, mixing prim tailoring with rebellious styling. Schoolgirl codes, mismatched layering, and saturated color create a knowing tension between innocence and disruption, reinforcing the brand’s identity as fashion’s cerebral ingénue.","images":["/api/assets/images/1771533693324-miu-miu-autumn-fall-winter-2014-pfw28.jpg","/api/assets/images/1771533695167-miu-miu0312.webp","/api/assets/images/1771533697142-miu-miu0512.webp","/api/assets/images/1771533698806-miu-miu0612.webp","/api/assets/images/1771533745579-miumiunux_color.600.600.avif","/api/assets/images/1771533747243-miu-miu-s16-005.webp","/api/assets/images/1771533749350-miu-miu-s16-003.webp","/api/assets/images/1771533751405-_MON0018.webp","/api/assets/images/1771533806736-miu-miu-resort-cruise-2019-paris-photos-03.webp","/api/assets/images/1771533809180-miumiu-cr19-11-7e3fc1.webp","/api/assets/images/1771533811070-00009-miu-miu-resort-2019-credit-indigital-model-naomi-campbell.webp","/api/assets/images/1771533813437-00006-miu-miu-resort-2019-credit-indigital-model-kiki-willems.webp"],"image_url":"/api/assets/images/1771533693324-miu-miu-autumn-fall-winter-2014-pfw28.jpg","caption":"As luxury grows more logo-driven, Miu Miu refocuses on character dressing, mixing prim tailoring with rebellious styling. Schoolgirl codes, mismatched layering, and saturated color create a knowing tension between innocence and disruption, reinforcing the brand’s identity as fashion’s cerebral ingénue."},{"title":"The Micro-Mini & Red Carpet Renaissance","year_range":"","description":"Post-2020, Miu Miu reclaims cultural dominance through radical proportion and viral minimalism. The Spring 2022 micro-mini skirt resets the youth conversation, while stripped-back tailoring and visible underpinnings redefine modern sensuality. Red carpet placements turn the brand into Gen-Z’s luxury uniform.","images":["/api/assets/images/1771533903861-_FIO0602.webp","/api/assets/images/1771533906159-00005-Miu-Miu-Spring-22-RTW-Paris-credit-gorunway.webp","/api/assets/images/1771533908181-miu-miu-mini-skirt-fall-2022.jpg","/api/assets/images/1771533909944-miumiu-ss22-look-33-67e85f.webp","/api/assets/images/1771533961726-37d24850-650b-4d55-b4ac-2bacee40d187-gettyimages-1471906411.avif","/api/assets/images/1771533963487-432770.jpg","/api/assets/images/1771533965338-Miu_Miu_AW23_Womenswear_057.width-1200_BoCTLtUSthTiqQj1.jpg","/api/assets/images/1771533967191-Miu_Miu_FW23_Fashionela-1.jpg","/api/assets/images/1771534156036-emma-chamberlain-spring-2024-miu-miu.jpg","/api/assets/images/1771534157905-Emma-Corrin-683x1024.webp","/api/assets/images/1771534160160-sydney-sweeney-spring-2024-miu-miu.jpg","/api/assets/images/1771534164130-shutterstock_editorial_13893708az-1682995822-600x900.jpg","/api/assets/images/1771534165851-xkpuEgXAAmEwCPqboysFEP-1600-80.jpg.webp"],"image_url":"/api/assets/images/1771533903861-_FIO0602.webp","caption":"Post-2020, Miu Miu reclaims cultural dominance through radical proportion and viral minimalism. The Spring 2022 micro-mini skirt resets the youth conversation, while stripped-back tailoring and visible underpinnings redefine modern sensuality. Red carpet placements turn the brand into Gen-Z’s luxury uniform."}]','[{"name":"Beau Leather Tote Bag","image_url":"/api/assets/images/1771534314272-P01106281.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-beau-leather-shoulder-bag-brown-p01106281"},{"name":"Plume Leather Sneakers","image_url":"/api/assets/images/1771534331666-P01170222.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-plume-leather-sneakers-brown-p01170222"},{"name":"Patchwork Plaid Wool Miniskirt","image_url":"/api/assets/images/1771534360534-P01146443.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-patchwork-plaid-virgin-wool-miniskirt-multicoloured-p01146443"},{"name":"Aventure Leather Tote Bag","image_url":"/api/assets/images/1771534381335-P01147777.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-aventure-leather-tote-bag-brown-p01147777"},{"name":"Suede Miniskirt","image_url":"/api/assets/images/1771534397486-P01117297.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-suede-miniskirt-brown-p01117297"},{"name":"Suede Jacket","image_url":"/api/assets/images/1771534415220-P01017187.avif","link":"https://www.mytheresa.com/euro/en/women/miu-miu-leather-jacket-brown-p01017187"}]','2026-02-19 20:53:39','2026-02-19 20:53:39');
INSERT INTO "designers" VALUES(12,'Valentino','valentino','val-en-TEE-noh ','/api/assets/audio/1771578598821-ElevenLabs_2026-02-20T09_09_51_Luca_Brasi_-_Intimate_and_Weighty_pvc_sp90_s50_sb75_se0_b_m2.mp3','The house is named for its founder, Valentino Garavani; “Valentino” derives from the Latin Valentinus (often associated with “strong/healthy”), while “Valentino Garavani” is used as the fuller signature on many products, especially accessories like bags and shoes.','/api/assets/images/1771575679940-VA921_SS26_NO-LOGO_DPS_PR_300DPI_08.jpg','Valentino Garavani','1960','Rome, Italy','Alessandro Michele','[{"name":"Couture","description":""},{"name":"Romantic","description":""},{"name":"Opulent","description":""},{"name":"Refined","description":""}]','[{"title":"Roman Atelier to International Arrival","year_range":"1960 - 1967","description":"Valentino builds a Roman couture identity with precise construction and a glamorous, old-world femininity, then pushes onto the international stage with a polished, unmistakably “house” point of view, Rome as both craft base and cultural signal.","images":["/api/assets/images/1771576238145-valentino-1712292629.jpg","/api/assets/images/1771576240007-Valentino-90th-Celebration-WWD-03.webp","/api/assets/images/1771576241705-365846.jpg","/api/assets/images/1771576243557-1968.webp","/api/assets/images/1771576245421-1b53a08ffbc6e05e34db66a19f6e7366.jpg","/api/assets/images/1771576248586-6f797662168de64b46ea2a296f30ee0b.jpg","/api/assets/images/1771576351822-007-valentino-theredlist.jpg","/api/assets/images/1771576354012-025-valentino-theredlist.jpg","/api/assets/images/1771576357699-063-valentino-theredlist.jpg","/api/assets/images/1771576359948-097-valentino-theredlist.jpg","/api/assets/images/1771576367357-valentino.jpg"],"image_url":"/api/assets/images/1771576238145-valentino-1712292629.jpg","caption":"Valentino builds a Roman couture identity with precise construction and a glamorous, old-world femininity, then pushes onto the international stage with a polished, unmistakably “house” point of view, Rome as both craft base and cultural signal."},{"title":"Jet-Set Couture and the Valentino Red Myth","year_range":"1968 - 2007","description":"The maison becomes a global shorthand for formal glamour: society dressing, couture ritual, and an instantly legible elegance. This is the long arc where “Valentino” reads like an institution: eveningwear authority with couture as the prestige engine.","images":["/api/assets/images/1771576615788-70s.jpeg","/api/assets/images/1771576617476-98ea21c52f0afacb90b4774cc09d9459.jpg","/api/assets/images/1771576619492-2900c68e27a2846ed85b61fb79d888cb.jpg","/api/assets/images/1771576625642-fashion-designs-by-valentino-30.jpeg","/api/assets/images/1771576627692-fashion-designs-by-valentino-32.jpeg","/api/assets/images/1771576631200-33644147861_2bc328ed85_b.jpg","/api/assets/images/1771576633533-a21309bc9ad63c1082ae0ab18ecd3311.jpg","/api/assets/images/1771576635945-c607002e22e861c2f21e5eb298467721.jpg","/api/assets/images/1771576639191-d8b80d6060f5d07f2afc31d6734c76e4.jpg","/api/assets/images/1771576811334-5b9934d75edbe94d2f7aa6836a2017d5.jpg","/api/assets/images/1771576813357-5bea0fe42ed6e1e7864123f777766489.jpg","/api/assets/images/1771576815544-6a3990fcf618aeb1fe562ba5b38757a8.jpg","/api/assets/images/1771576817562-321a2d392d1145e36c1349307549a160.jpg","/api/assets/images/1771576819854-1828eeeb52c8c65297cb786bfc654347.jpg","/api/assets/images/1771576824207-1652194464654-gettyimages-124079799.webp","/api/assets/images/1771576825868-b2f1abe8d8744ef2ddd4d9551f7678ca.jpg"],"image_url":"/api/assets/images/1771576615788-70s.jpeg","caption":"The maison becomes a global shorthand for formal glamour: society dressing, couture ritual, and an instantly legible elegance. This is the long arc where “Valentino” reads like an institution: eveningwear authority with couture as the prestige engine."},{"title":"The New Guard and the Rockstud Revolution","year_range":"2008 - 2015","description":"A new leadership phase modernizes the house’s romance with sharper edges and accessories that travel fast through street style and celebrity styling. Valentino’s public-facing signature shifts from pure couture mythology to objects: shoes and bags that photograph instantly.","images":["/api/assets/images/1771577110675-1_master.jpg","/api/assets/images/1771577112711-00010fullscreen_1_.webp","/api/assets/images/1771577114465-00010fullscreen.webp","/api/assets/images/1771577116717-00060fullscreen.webp","/api/assets/images/1771577118971-690f8dfb55a00ca150cbd6da8a58fbef.jpg","/api/assets/images/1771577120870-sytle_dot_com_valentino_fall_2012_black_sleveless_sparkle_gown_cococozy.jpg","/api/assets/images/1771577124020-valentino02.webp"],"image_url":"/api/assets/images/1771577110675-1_master.jpg","caption":"A new leadership phase modernizes the house’s romance with sharper edges and accessories that travel fast through street style and celebrity styling. Valentino’s public-facing signature shifts from pure couture mythology to objects: shoes and bags that photograph instantly."},{"title":"Modern Couture Humanism to Michele’s Maximal Shift","year_range":"2016 - present","description":"Piccioli reframes couture as contemporary emotion: color, proportion, and inclusive casting used to refresh Roman grandeur for now. With Alessandro Michele’s appointment, the house pivots toward denser, referential storytelling while staying anchored in couture technique.","images":["/api/assets/images/1771577596415-valentino-hc-po-s22-043-10632630.jpg","/api/assets/images/1771577598308-VALENTINO-ANATOMY-OF-COUTURE-6.jpg","/api/assets/images/1771577600164-2415e40fed8d56bb100a7828ffe992d5.jpg","/api/assets/images/1771577602381-af30a121-257d-4d64-9eb7-0a8bf4ae7036.avif","/api/assets/images/1771577605043-423618.jpg","/api/assets/images/1771577608129-00077-valentino-fall-2022-couture-credit-gorunway.webp","/api/assets/images/1771577613137-valentino-rtw-fall-22-pfw001.webp","/api/assets/images/1771577615157-Valentino-Fall-Winter-2022-2023-Runway-Magazine-81.jpg","/api/assets/images/1771577618067-IMG_7539-scaled.jpg","/api/assets/images/1771577748711-001_VALENTINO_HC25.jpg","/api/assets/images/1771577750867-paris-france-january-29.avif","/api/assets/images/1771577752709-456293.webp","/api/assets/images/1771577756927-gettyimages-2196585444.avif","/api/assets/images/1771577759697-4fb49ad8-7069-4847-9624-0c7c9db2d76e.avif","/api/assets/images/1771577761474-4503a32e-be99-49ac-a158-99bc4daac7d3.avif","/api/assets/images/1771577763870-acfb17f1-bf67-4526-baa6-4a8453ab3bf8.avif","/api/assets/images/1771577767684-cfdc738a-d3cd-4c05-a363-e863dafd0d97.avif"],"image_url":"/api/assets/images/1771577596415-valentino-hc-po-s22-043-10632630.jpg","caption":"Piccioli reframes couture as contemporary emotion: color, proportion, and inclusive casting used to refresh Roman grandeur for now. With Alessandro Michele’s appointment, the house pivots toward denser, referential storytelling while staying anchored in couture technique."},{"title":"Iconic Culture Moments Canon","year_range":"1968 - 2026","description":"This is the public memory era: Valentino becomes a cultural reference point through a handful of looks and moments that outlive seasons, society mythology, red carpet canon, and the archive’s afterlife as a source of modern icons.","images":["/api/assets/images/1771577889115-0047565933.original.webp","/api/assets/images/1771577891127-FA00029802_0006_Enhanced-1.webp","/api/assets/images/1771578165375-3040fdfdc28056526ab6708872e97529.jpg","/api/assets/images/1771578168122-IMG_9752.webp","/api/assets/images/1771578171946-IMG_9759.webp","/api/assets/images/1771578174395-princess-diana-valentino-red-dress-1992-gettyimages-1309284492-2.webp","/api/assets/images/1771578195831-IMG_9751.webp","/api/assets/images/1771578200570-IMG_9757.webp","/api/assets/images/1771578203568-IMG_9755.webp","/api/assets/images/1771578217327-IMG_9754.webp","/api/assets/images/1771578240174-GettyImages-56601915.webp","/api/assets/images/1771578241967-GettyImages-75507964.webp","/api/assets/images/1771578245467-IMG_9758.webp","/api/assets/images/1771578247442-IMG_9756.webp","/api/assets/images/1771578251342-GettyImages-2202517767.webp","/api/assets/images/1771578253018-zendaya-valentino-dress-spring-summer-1992-collection-black-and-white-striped-gown-law-roach-luxurylaw.webp"],"image_url":"/api/assets/images/1771577889115-0047565933.original.webp","caption":"This is the public memory era: Valentino becomes a cultural reference point through a handful of looks and moments that outlive seasons, society mythology, red carpet canon, and the archive’s afterlife as a source of modern icons."}]','[{"name":"Cherryfic 55 Leather Mules","image_url":"/api/assets/images/1771578828274-P01130242.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-garavani-cherryfic-55-leather-mules-white-p01130242"},{"name":"Crepe Couture Minidress","image_url":"/api/assets/images/1771578851361-P01108243.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-crepe-couture-bow-detail-embellished-minidress-white-p01108243"},{"name":"Crepe Couture Bow Minidress","image_url":"/api/assets/images/1771578877943-P01108327.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-crepe-couture-bow-detail-minidress-red-p01108327"},{"name":"Laseine Striped Tote Bag","image_url":"/api/assets/images/1771578899157-P01127120.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-garavani-laseine-large-striped-tote-bag-black-p01127120"},{"name":"Yolande Bow Satin Mules","image_url":"/api/assets/images/1771578931278-P01130525.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-garavani-yolande-45-bow-trimmed-satin-mules-red-p01130525"},{"name":"Crepe Couture Cropped Jacket","image_url":"/api/assets/images/1771578950442-P01107841.avif","link":"https://www.mytheresa.com/euro/en/women/valentino-crepe-couture-bow-detail-cropped-jacket-black-p01107841"}]','2026-02-20 09:15:55','2026-02-20 09:15:55');
INSERT INTO "designers" VALUES(13,'Burberry','burberry','BUR-ber-ee','/api/assets/audio/1771579532457-Burberry_3.mp3','Burberry is the founder’s surname, named for Thomas Burberry, who started the business as an outfitter rooted in British outdoor clothing.','/api/assets/images/1771579891796-burberry-london-love-1.avif','Thomas Burberry','1856','Basingstoke, Hampshire, England','Daniel Lee','[{"name":"Heritage","description":""},{"name":"Classic","description":""},{"name":"Tailoring","description":""},{"name":"Luxury","description":""}]','[{"title":"Gabardine Origins & Military Outerwear","year_range":"1856 - 1919","description":"Burberry builds its identity as performance outerwear before “luxury” is the point, innovating materials, then translating function into recognizable design codes that will become the house’s long-term signature language.","images":["/api/assets/images/1771580063422-36aec2ea-56f0-4a6c-b03a-32fbec4e063b_434x900.jpg","/api/assets/images/1771580065462-20171106083702.jpg","/api/assets/images/1771580067301-project_47_.jpg","/api/assets/images/1771580114500-project_50_.jpg","/api/assets/images/1771580144921-project_51_.jpg","/api/assets/images/1771580148296-thomasburberry_2.webp"],"image_url":"/api/assets/images/1771580063422-36aec2ea-56f0-4a6c-b03a-32fbec4e063b_434x900.jpg","caption":"Burberry builds its identity as performance outerwear before “luxury” is the point, innovating materials, then translating function into recognizable design codes that will become the house’s long-term signature language."},{"title":"Check Emergence & Global Recognition","year_range":"1920 - 1996","description":"The brand’s codes shift from purely utilitarian to instantly legible: the Check begins as an interior detail, then becomes a public facing identifier as Burberry grows into a globally recognized symbol of British dress and travel culture.","images":["/api/assets/images/1771580446381-1_dcb08638-9a28-4184-9789-61345be2975c_600x600.webp","/api/assets/images/1771580449324-d8a579b16dc9a2207bcc19d39bcd5e26.jpg","/api/assets/images/1771580452238-7B1549BF-74FB-40AC-A5EA-07BC875447C1.webp","/api/assets/images/1771580454541-2b19911fd6443d9e124d9441d95087bd.jpg","/api/assets/images/1771580458164-4960b2eaf0223851f1b42610bb3ed2f3.jpg","/api/assets/images/1771580462489-tumblr_e82c5f6925f0f44b44526d52437af096_841eff91_1280.jpg","/api/assets/images/1771580464607-tumblr_pmvmd3kbJ81y10mico1_640.jpg","/api/assets/images/1771580466591-3_ad29ee5e-86ab-4fdd-b988-74027c6caff5_600x600.webp"],"image_url":"/api/assets/images/1771580446381-1_dcb08638-9a28-4184-9789-61345be2975c_600x600.webp","caption":"The brand’s codes shift from purely utilitarian to instantly legible: the Check begins as an interior detail, then becomes a public facing identifier as Burberry grows into a globally recognized symbol of British dress and travel culture."},{"title":"Modern Luxury Rebuild: Bailey & the Digital House","year_range":"1997 - 2017","description":"Burberry refines from legacy outfitter into a modern luxury system: brand identity tightens, runway becomes a global media engine, and heritage outerwear is re-staged with a contemporary polish designed for scale without losing Britishness.","images":["/api/assets/images/1771580702100-100064122.webp","/api/assets/images/1771580704170-00180m.webp","/api/assets/images/1771580706480-00170m.webp","/api/assets/images/1771580708876-00170m_1_.webp","/api/assets/images/1771580710768-00140m.webp","/api/assets/images/1771580712996-00080m.webp","/api/assets/images/1771580715486-00060m.webp","/api/assets/images/1771580719118-00040m.webp","/api/assets/images/1771580721434-00010m.webp","/api/assets/images/1771580723640-00010m_1_.webp","/api/assets/images/1771580849653-00010fullscreen.webp","/api/assets/images/1771580851869-00030fullscreen.webp","/api/assets/images/1771580854103-00190fullscreen.webp","/api/assets/images/1771580858326-_BUR0018.1366x2048.webp","/api/assets/images/1771580860259-_BUR0031.1366x2048.webp","/api/assets/images/1771580864342-_BUR0096.1366x2048.webp","/api/assets/images/1771580866702-_BUR0165.1366x2048.webp"],"image_url":"/api/assets/images/1771580702100-100064122.webp","caption":"Burberry refines from legacy outfitter into a modern luxury system: brand identity tightens, runway becomes a global media engine, and heritage outerwear is re-staged with a contemporary polish designed for scale without losing Britishness."},{"title":"Rebrand to Re-root:  Tisci to Lee","year_range":"2018 - present","description":"The house toggles between street coded modernity and heritage clarity: Tisci introduces a bold new identity system, then Lee re-centers “Burberry weather” Britishness: outerwear, countryside cues, and recognizable icons, while modernizing proportions and attitude.","images":["/api/assets/images/1771581059387-Burberry4_gorunway.webp","/api/assets/images/1771581061098-Burberry3_gorunway.webp","/api/assets/images/1771581062897-Burberry-Ready-To-Wear-Fall-Winter-2020-London-Fashion-Week-Runway-057.webp","/api/assets/images/1771581065130-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_03_burberry-fw22-collection-runway-show-2.avif","/api/assets/images/1771581067397-1321887.webp","/api/assets/images/1771581072209-https_hypebeast.com_image_2022_09_burberry-spring-summer-2023-runway-show-london-fashion-week-riccardo-tisci-59.avif","/api/assets/images/1771581074392-https_hypebeast.com_wp-content_blogs.dir_6_files_2022_09_Burberry-Spring_Summer-2023-Collection-Look-56-scaled.avif","/api/assets/images/1771581076862-https_kr.hypebeast.com_files_2022_09_burberry-spring-summer-2023-runway-riccardo-tisci-show-london-fashion-week-68.avif","/api/assets/images/1771581143349-5380d331-4bf0-48a1-b376-17aa206e9b77-aea4c611-d1b4-42ff-abbc-fb80294f8b36-gettyimages-1427550179.avif","/api/assets/images/1771581163902-3826.avif","/api/assets/images/1771581166440-burb-2-65d3d1adc46f1.avif","/api/assets/images/1771581174088-https_hypebeast.com_image_2024_02_burberry-fall-winter-2024-london-fashion-week-menswear-womenswear-daniel-lee-runway-40.png","/api/assets/images/1771581500600-burberry-f25-046-67bd9c64b4663.avif","/api/assets/images/1771581502371-burberry-f25-053-1-67bdaff26dd4b.avif","/api/assets/images/1771581504377-burberry-winter-2025-show-look-11.jpeg","/api/assets/images/1771581508978-gettyimages-2201223386.avif","/api/assets/images/1771581511712-burberrysummer2025showrunwayfronts2346-6e226dcf.webp","/api/assets/images/1771581513979-gettyimages-2171670561.avif","/api/assets/images/1771581516618-oby1226-11438039.jpg"],"image_url":"/api/assets/images/1771581059387-Burberry4_gorunway.webp","caption":"The house toggles between street coded modernity and heritage clarity: Tisci introduces a bold new identity system, then Lee re-centers “Burberry weather” Britishness: outerwear, countryside cues, and recognizable icons, while modernizing proportions and attitude."}]','[{"name":"Trench Coat","image_url":"/api/assets/images/1771581617729-P01143367.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-cotton-trench-coat-beige-p01143367"},{"name":"Cotton Gabardine Midi Skirt","image_url":"/api/assets/images/1771581645201-P01143368.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-cotton-gabardine-maxi-skirt-green-p01143368"},{"name":"Belted Trench Coat","image_url":"/api/assets/images/1771581664533-P01143355.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-belted-trench-coat-beige-p01143355"},{"name":"Burberry Check Jacket","image_url":"/api/assets/images/1771581684083-P01143369.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-burberry-check-cotton-jacket-beige-p01143369"},{"name":"Floriston Quilted Jacket","image_url":"/api/assets/images/1771581715803-P01143350.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-floriston-quilted-jacket-brown-p01143350"},{"name":"Burberry Check Wool Midi Skirt","image_url":"/api/assets/images/1771581747330-P01143361.avif","link":"https://www.mytheresa.com/euro/en/women/burberry-burberry-check-wool-midi-skirt-brown-p01143361"}]','2026-02-20 10:02:29','2026-02-20 10:02:29');
INSERT INTO "designers" VALUES(14,'Givenchy','givenchy','zhuh-von-SHEE','/api/assets/audio/1771581998592-Givenchy_2.mp3','“Givenchy” is Hubert de Givenchy’s family name (a French toponymic surname tied to place names in northern France). As a house name, it signals lineage: aristocratic polish, Paris couture discipline, and a very personal founder-led identity.','/api/assets/images/1771582001312-GIVENCHY-HERO-11.jpg','Hubert de Givenchy','1952','Paris, France','Sarah Burton','[{"name":"Couture","description":""},{"name":"Refined","description":""},{"name":"Romantic","description":""},{"name":"Structured","description":""}]','[{"title":"The Givenchy Code: Youthful Couture","year_range":"1952 - 1988","description":"Givenchy builds a modern couture house around separates, clean line, and intimate elegance, then cements it through cinema, especially Audrey Hepburn. The identity is refined but light-footed: impeccable craft made legible in everyday life and on screen fantasy.","images":["/api/assets/images/1771582204345-blouse-signature-portee-par-mannequin-bettina-graziani-1952-308x410.webp","/api/assets/images/1771582206438-1168ecb59812be2579948905a656d5ae.jpg","/api/assets/images/1771582208432-GIVENCHY-HERO-11-789x1000.jpeg","/api/assets/images/1771582299004-5de812_3f228ce1c7d0da1dd0dacb19ddff12d2.avif","/api/assets/images/1771582301041-5de812_d2001c28cf26c270ba342053266d27f9.avif","/api/assets/images/1771582302935-audrey-2.jpg","/api/assets/images/1771582372914-hepburn_3371478a.webp","/api/assets/images/1771582374885-audrey-hepburn-by-hubert-de-givenchy-part-i-v0-3sw0uw7rfbtc1.webp","/api/assets/images/1771582377058-02-audrey-hepburn-x-givenchy.webp","/api/assets/images/1771582380873-00-story-audrey-hepburn-x-givenchy.webp","/api/assets/images/1771582474566-66aff3d9b2fe51fca3aaeab7d0a995f7.jpg","/api/assets/images/1771582476552-778bf76c8db17ba7ffbbb1677ffad778.jpg","/api/assets/images/1771582478452-c588de44ea5bc241c41ba222714acd4c.jpg","/api/assets/images/1771582480625-givenchy86.webp"],"image_url":"/api/assets/images/1771582204345-blouse-signature-portee-par-mannequin-bettina-graziani-1952-308x410.webp","caption":"Givenchy builds a modern couture house around separates, clean line, and intimate elegance, then cements it through cinema, especially Audrey Hepburn. The identity is refined but light-footed: impeccable craft made legible in everyday life and on screen fantasy."},{"title":"Post-Founder Reboot: British Shock & Spectacle","year_range":"1988 - 2005","description":"After LVMH’s acquisition, Givenchy enters a high voltage transition where John Galliano and then Alexander McQueen: two British talents with radically theatrical instincts, push the house into a more confrontational, show-driven language. Even as couture technique anchors the work, the runway becomes a proving ground for provocation, mood, and modern myth-making.","images":["/api/assets/images/1771582714021-450_1000.jpg","/api/assets/images/1771582715876-tumblr_o9h70waC831qm3zbto1_500.jpg","/api/assets/images/1771582717870-tumblr_n4hhdtOdur1qm3zbto1_1280.jpg","/api/assets/images/1771582721241-012-givenchy-by-john-galliano-fall-1996-couture-CN10004660.webp","/api/assets/images/1771582723881-008-givenchy-by-john-galliano-fall-1996-couture-CN10004667-kate-moss.webp","/api/assets/images/1771582726545-003-givenchy-by-john-galliano-fall-1996-couture-CN10004674-georgina-grenville.webp","/api/assets/images/1771582730502-002-givenchy-spring-1996-couture-CN10054163-ines-rivero.webp","/api/assets/images/1771582732639-001-givenchy-by-john-galliano-fall-1996-couture-CN10004669-debbie-deitering.webp","/api/assets/images/1771582972030-spring-1997-9_1_.jpg","/api/assets/images/1771582974839-MCQUEEN_GIVENCHY_NIKE_III.webp","/api/assets/images/1771582977851-d0aebb8d82bf386f07ec8dcfa8b95d95.jpg","/api/assets/images/1771582980098-1487865728-naomi.avif","/api/assets/images/1771582986322-1b12b7a19259cd37eefaf0b5bdb184aa.jpg","/api/assets/images/1771583003885-41debb92b5331e88a5aef19ee400a2a5.jpg","/api/assets/images/1771583006008-55a1da8cf2bfdac860096684957740b5.jpg","/api/assets/images/1771583008032-5100627f2ae0066587ee413c904450b3.jpg","/api/assets/images/1771583012825-McQueen_for_Givenchy_Dress_master.jpeg"],"image_url":"/api/assets/images/1771582714021-450_1000.jpg","caption":"After LVMH’s acquisition, Givenchy enters a high voltage transition where John Galliano and then Alexander McQueen: two British talents with radically theatrical instincts, push the house into a more confrontational, show-driven language. Even as couture technique anchors the work, the runway becomes a proving ground for provocation, mood, and modern myth-making."},{"title":"Tisci’s Dark Romance & Icon Accessories","year_range":"2005 - 2017","description":"Riccardo Tisci redefines Givenchy for the modern celebrity ecosystem: couture technique meets a sharper, darker sensuality, and accessories become cultural shorthand. The house’s elegance turns graphic and muscular, creating a new template for Paris luxury with global pop reach.","images":["/api/assets/images/1771583174696-58935f8a749783922af6bb82_GettyImages-72089862_master.avif","/api/assets/images/1771583176470-58935f8ce15460f508bf078c_GettyImages-73089851_master.avif","/api/assets/images/1771583178812-58935f8d749783922af6bb84_GettyImages-73459488_master.avif","/api/assets/images/1771583180643-58935f8de15460f508bf078e_GettyImages-73551784_master.avif","/api/assets/images/1771583182415-58935f8e8a79b5644d6f5908_GettyImages-75028820_master.avif","/api/assets/images/1771583184606-58935f8f8a79b5644d6f590a_GettyImages-80045990_master.avif","/api/assets/images/1771583186901-58935f9ae15460f508bf0798_GettyImages-88886292_master.avif","/api/assets/images/1771583191627-58935f9be15460f508bf079c_GettyImages-96203389_master.avif","/api/assets/images/1771583193419-58935f9c749783922af6bb8e_GettyImages-97515469_master.avif","/api/assets/images/1771583195096-58935f9e749783922af6bb94_GettyImages-140687305_master.avif","/api/assets/images/1771583196768-58935f90e15460f508bf0790_GettyImages-83104363_master.avif","/api/assets/images/1771583198609-58935f97e15460f508bf0792_GettyImages-79174604_master.avif","/api/assets/images/1771583200357-58935f98e15460f508bf0793_GettyImages-84510835_master.avif","/api/assets/images/1771583202625-58935f98e15460f508bf0796_GettyImages-85375265_master.avif","/api/assets/images/1771583205334-58935f988a79b5644d6f590c_GettyImages-85375401_master.avif","/api/assets/images/1771583206955-58935f90749783922af6bb86_GettyImages-77303837_master.avif","/api/assets/images/1771583211497-58935f97749783922af6bb88_GettyImages-85303230_master.avif","/api/assets/images/1771583213274-58935f99749783922af6bb8a_GettyImages-88886287_master.avif","/api/assets/images/1771583214880-58935fae749783922af6bba6_GettyImages-639381304_master.avif"],"image_url":"/api/assets/images/1771583174696-58935f8a749783922af6bb82_GettyImages-72089862_master.avif","caption":"Riccardo Tisci redefines Givenchy for the modern celebrity ecosystem: couture technique meets a sharper, darker sensuality, and accessories become cultural shorthand. The house’s elegance turns graphic and muscular, creating a new template for Paris luxury with global pop reach."},{"title":"Recalibration to Craft: From Keller & Williams to Burton","year_range":"2017 - present","description":"Givenchy spends these years re-tuning its DNA: first a return to polished Paris femininity and ceremony, then a tougher, street-influenced edge, before Sarah Burton’s appointment signals a deliberate pivot back toward cut, construction, and atelier authority.","images":["/api/assets/images/1771583345035-1629211067-givenchy-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583347121-1629211075-givenchy-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583349284-1629211081-givenchy-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583351367-1629211297-givenchy-couture-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583353229-1629211305-givenchy-couture-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583355075-1629211311-givenchy-couture-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583357559-1629211317-givenchy-couture-ss18-clare-waight-keller-runway.webp","/api/assets/images/1771583359616-1629211983-givenchy-couture-ss19-clare-waight-keller-runway.webp","/api/assets/images/1771583361407-1629212201-givenchy-couture-ss20-clare-waight-keller-runway.webp","/api/assets/images/1771583446650-2d25.avif","/api/assets/images/1771583448360-00052-givenchy-spring-2024-ready-to-wear-credit-gorunway.jpg.webp","/api/assets/images/1771583450928-givenchy-s24-41-1600x2400-1742423335500-u08qs9er74.jpg","/api/assets/images/1771583452892-https_hypebeast.com_wp-content_blogs.dir_6_files_2023_03_Givenchy-FW23-Womenswear-look-45.avif","/api/assets/images/1771583535384-78f3.avif","/api/assets/images/1771583537077-2732.avif","/api/assets/images/1771583539131-465542.avif","/api/assets/images/1771583541102-ZOO6U453WBE6RISFLOQ2J6OPBM.avif"],"image_url":"/api/assets/images/1771583345035-1629211067-givenchy-ss18-clare-waight-keller-runway.webp","caption":"Givenchy spends these years re-tuning its DNA: first a return to polished Paris femininity and ceremony, then a tougher, street-influenced edge, before Sarah Burton’s appointment signals a deliberate pivot back toward cut, construction, and atelier authority."}]','[{"name":"Shark Knee High Boots","image_url":"/api/assets/images/1771583654391-P01128247.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-shark-95-leather-knee-high-boots-black-p01128247"},{"name":"Cotton Poplin Shirt","image_url":"/api/assets/images/1771583677475-P01124968.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-cotton-poplin-shirt-white-p01124968"},{"name":"Antigona Leather Vanity Bag","image_url":"/api/assets/images/1771583700984-P01126190.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-antigona-leather-vanity-bag-burgundy-p01126190"},{"name":"Embellished Halterneck Top","image_url":"/api/assets/images/1771583721498-P01124970.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-embellished-halterneck-top-black-p01124970"},{"name":"Voyou Suede Shoulder Bag","image_url":"/api/assets/images/1771583756160-P01155590.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-voyou-medium-leather-shoulder-bag-brown-p01155590"},{"name":"Bow Detail Midi Dress","image_url":"/api/assets/images/1771583778562-P01124934.avif","link":"https://www.mytheresa.com/euro/en/women/givenchy-bow-detail-midi-dress-white-p01124934"}]','2026-02-20 10:36:23','2026-02-20 10:36:23');
INSERT INTO "designers" VALUES(15,'Chloé','chlo','kloh-AY','/api/assets/audio/1771592267106-Chloe_.mp3','“Chloé” comes from the Greek Chlóē, meaning “green shoot / new growth”, an epithet linked to Demeter, goddess of agriculture and fertility.','/api/assets/images/1771592309417-Chloe-Spring-Summer-2026-Campaign01.jpg','Gaby Aghion','1952','Paris, France','Chemena Kamali','[{"name":"Romantic","description":""},{"name":"Bohemian","description":""},{"name":"Feminine","description":""},{"name":"Refined","description":""}]','[{"title":"Luxury Ready to Wear is Born","year_range":"1952 - 1966","description":"Chloé establishes a softer alternative to mid century formality, championing luxury prêt-à-porter with relaxed silhouettes and refined finishing. The house builds its identity around ease, feminine movement, and a modern wardrobe designed for real life.","images":["/api/assets/images/1771593067169-06.jpg","/api/assets/images/1771593071479-Maison_history_1958.avif","/api/assets/images/1771593075095-Maison_history_1960.avif","/api/assets/images/1771593077560-Maison_History_1962.avif","/api/assets/images/1771593079708-Maison_History_1965_1_.avif","/api/assets/images/1771593081966-Maison_History_1969.avif","/api/assets/images/1771593085261-Maison_History_1973.avif","/api/assets/images/1771593087367-Maison_History_1974.avif"],"image_url":"/api/assets/images/1771593067169-06.jpg","caption":"Chloé establishes a softer alternative to mid century formality, championing luxury prêt-à-porter with relaxed silhouettes and refined finishing. The house builds its identity around ease, feminine movement, and a modern wardrobe designed for real life."},{"title":"The Lagerfeld Years: Parisian Romance, 70s Ease","year_range":"1966 - 1996","description":"Under Karl Lagerfeld’s long influence, Chloé becomes a reference point for romantic, airy Paris dressing, translating runway fantasy into wearable glamour. The brand’s signature lightness and femininity sharpen into a globally legible house code.","images":["/api/assets/images/1771593375768-chloe-archives-012.webp","/api/assets/images/1771593378557-karl-lagerfeld-chloe-special-issue-1.webp","/api/assets/images/1771593380608-karl-lagerfeld-chloe-special-issue-2.webp","/api/assets/images/1771593383271-karl-lagerfeld-chloe-special-issue-3.webp","/api/assets/images/1771593385235-karl-lagerfeld-chloe-special-issue-4.webp","/api/assets/images/1771593536251-29KARLLOOKS-CHLOE-06-mobileMasterAt3x.jpg","/api/assets/images/1771593538205-GettyImages-124120562.webp","/api/assets/images/1771593540104-GettyImages-1438042639.webp","/api/assets/images/1771593542544-karl-lagerfeld-chloe-special-issue-6.webp","/api/assets/images/1771593689827-Chloe1994WomenRTW162.webp","/api/assets/images/1771593691609-EMERIEU-Chloe-Spring-Summer-1994-floral-mesh-maxi-dress-reference1.webp","/api/assets/images/1771593695046-karl-lagerfeld-chloe-special-issue-7.webp","/api/assets/images/1771593696962-karl-lagerfeld-chloe-special-issue-8.webp","/api/assets/images/1771593700865-karl-lagerfeld-chloe-special-issue-9.webp","/api/assets/images/1771593702491-karl-lagerfeld-chloe-special-issue-10.webp"],"image_url":"/api/assets/images/1771593375768-chloe-archives-012.webp","caption":"Under Karl Lagerfeld’s long influence, Chloé becomes a reference point for romantic, airy Paris dressing, translating runway fantasy into wearable glamour. The brand’s signature lightness and femininity sharpen into a globally legible house code."},{"title":"It Girl Modernity: McCartney to Philo","year_range":"1997 - 2006","description":"Chloé pivots into a younger, cooler kind of femininity: playful, slightly undone, and attitude forward, then crystallizes into early-2000s desirability. Accessories become a cultural engine, culminating in the era’s defining “It” bag moment.","images":["/api/assets/images/1771594018134-chloe-fall-winter-1998-3.webp","/api/assets/images/1771594019910-fa51263f509302b4b23d39b534c5c480.jpg","/api/assets/images/1771594022029-IMG_7805_master.jpg","/api/assets/images/1771594024351-tumblr_58c314de19ca3637fb2b1b72c2dd8243_3524d2e4_540.jpg","/api/assets/images/1771594036662-bc134308f540d875774ab546c8f3fc31.jpg","/api/assets/images/1771594045380-500x700-05-13-scaled.jpg","/api/assets/images/1771594048326-004-chloe-spring-2000-ready-to-wear-CN10017627-trish-goff.webp","/api/assets/images/1771594052171-251a77367ddedff4392908f6b34cd052.jpg","/api/assets/images/1771594054804-2000.webp","/api/assets/images/1771594056975-cfe25751bbb39a778bc089836fdd527c.jpg","/api/assets/images/1771594175569-chloe-set2-ss02-0009-5g6b4plh-2023-06-29.avif","/api/assets/images/1771594177672-chloe-ss06-0031-z9lo4qyb-2023-06-29.avif","/api/assets/images/1771594180106-chloe-ss05-073-s65yh3m4-2023-06-29.avif","/api/assets/images/1771594181910-chloe-set2-ss02-0076-ddl5y0k3-2023-06-29.avif","/api/assets/images/1771594183959-00050h-chloe-spring-2005-ready-to-wear-erin-wasson.webp","/api/assets/images/1771594189010-00050h-chloe-spring-2003-ready-to-wear-erin-wasson.webp","/api/assets/images/1771594190598-00040h-chloe-spring-2003-ready-to-wear-dewi-driegen.webp","/api/assets/images/1771594192632-00010h-chloe-fall-2005-ready-to-wear-gemma-ward.webp"],"image_url":"/api/assets/images/1771594018134-chloe-fall-winter-1998-3.webp","caption":"Chloé pivots into a younger, cooler kind of femininity: playful, slightly undone, and attitude forward, then crystallizes into early-2000s desirability. Accessories become a cultural engine, culminating in the era’s defining “It” bag moment."},{"title":"Craft, Conscience & Boho Reboot","year_range":"2007 - 2026","description":"Chloé spends the 2010s refining its house essentials: romantic daywear and leather goods with artisanal detail, then pushes harder into responsibility and traceability in the early 2020s. Under Kamali, the brand re-centers its heritage codes with a renewed, modern bohemian energy.","images":["/api/assets/images/1771594365260-5866663c1ae1e070040f2262594f9d9d.jpg","/api/assets/images/1771594371910-chloe-rtw-spring-summer-2018-paris-fashion-week-3098.webp","/api/assets/images/1771594374274-chloe-spring-2018-rtw-slide-ZJR2-superJumbo.webp","/api/assets/images/1771594376411-Chloe-Spring-Summer-2020-Runway42-450x700.jpg","/api/assets/images/1771594378427-ALE0250-1-1200x1800.jpg","/api/assets/images/1771594380949-chloe-rtw-fall-2020-pfw-1985.webp","/api/assets/images/1771594441513-5ed2130b-bf58-4e47-b490-ebc3e49fce4c-chloe-f24-052.avif","/api/assets/images/1771594443415-chloe-fall-winter-2024-runway-1.webp","/api/assets/images/1771594445296-chloe-fall-winter-2024-runway-7.webp","/api/assets/images/1771594447268-chloe-fall-winter-2024-runway-11.webp","/api/assets/images/1771594450124-edf2c8bd0ccb2e437f93b1f31107b60f.webp","/api/assets/images/1771594495894-chloe-fall-25-rtw-r-gg-004.webp","/api/assets/images/1771594498006-gettyimages-2203593483.avif","/api/assets/images/1771594499954-gettyimages-2203594008.avif","/api/assets/images/1771594503776-isi01568-11468092-1.jpg"],"image_url":"/api/assets/images/1771594365260-5866663c1ae1e070040f2262594f9d9d.jpg","caption":"Chloé spends the 2010s refining its house essentials: romantic daywear and leather goods with artisanal detail, then pushes harder into responsibility and traceability in the early 2020s. Under Kamali, the brand re-centers its heritage codes with a renewed, modern bohemian energy."}]','[{"name":"Silk Maxi Dress","image_url":"/api/assets/images/1771594592002-P01104933.avif","link":"https://www.mytheresa.com/euro/en/women/chloe-silk-midi-dress-beige-p01104933"},{"name":"Embellished Leather Bag","image_url":"/api/assets/images/1771594616305-P01105773.webp","link":"https://www.mytheresa.com/euro/en/women/chloe-embellished-leather-tote-bag-brown-p01105773"},{"name":"Ruffled Silk Minidress","image_url":"/api/assets/images/1771594644215-P01104941.avif","link":"https://www.mytheresa.com/euro/en/women/chloe-ruffled-silk-muslin-minidress-pink-p01104941"},{"name":"Eden Treasures Small Bucket Bag","image_url":"/api/assets/images/1771594669056-P01105776.avif","link":"https://www.mytheresa.com/euro/en/women/chloe-eden-treasures-small-suede-bucket-bag-burgundy-p01105776"},{"name":"Virgin Wool Shorts","image_url":"/api/assets/images/1771594689015-P01130775.avif","link":"https://www.mytheresa.com/euro/en/women/chloe-virgin-wool-shorts-black-p01130775"},{"name":"Lace Trimmed Silk Blouse","image_url":"/api/assets/images/1771594709013-P01089544.avif","link":"https://www.mytheresa.com/euro/en/women/chloe-lace-trimmed-silk-blouse-pink-p01089544"}]','2026-02-20 13:38:32','2026-02-20 13:38:32');
INSERT INTO "designers" VALUES(16,'Acne Studios','acne-studios','AK-nee STU-dee-ohz','/api/assets/audio/1771595076343-Acne_Studios.mp3','“Acne” comes from the original multidisciplinary collective ACNE- first used as an acronym (“Associated Computer Nerd Enterprises”) and later reframed as “Ambition to Create Novel Expressions.”','/api/assets/images/1771595078144-acne-studios-fall-2024-ad-campaign-the-impression-header.jpg','Jonny Johansson, Mats Johansson, Jesper Kouthoofd & Tomas Skoging','1996','Stockholm, Sweden','Jonny Johansson','[{"name":"Minimalist","description":""},{"name":"Modernist","description":""},{"name":"Androgynous","description":""},{"name":"Experimental","description":""}]','[{"title":"From Collective to Culture House","year_range":"1996 - 2008","description":"Acne begins as a multidisciplinary Stockholm collective and uses fashion as a cultural signal: first through cult raw denim, then through a widening ready to wear offer. By the mid 2000s, the house formalizes its world through Acne Paper, and closes the era by stepping decisively onto the Paris stage with both the Palais Royal boutique and a high profile collaboration with Lanvin, signaling its transition from Scandinavian insider brand to global luxury player.","images":["/api/assets/images/1771675565727-acne3.jpg","/api/assets/images/1771675568307-acne27.jpg","/api/assets/images/1771675571241-acne101.jpg","/api/assets/images/1771675574236-acne37-198x300.jpg","/api/assets/images/1771675576624-acne39.jpg","/api/assets/images/1771675582528-Bild_1_8.png","/api/assets/images/1771675587227-original_1_.webp","/api/assets/images/1771675591023-AP_1.jpg","/api/assets/images/1771675592767-AP_2.jpg","/api/assets/images/1771675594625-AP_3.jpg","/api/assets/images/1771675596468-AP_4.jpg","/api/assets/images/1771675603210-AP_5.jpg","/api/assets/images/1771675605340-AP_6.jpg"],"image_url":"/api/assets/images/1771675565727-acne3.jpg","caption":"Acne begins as a multidisciplinary Stockholm collective and uses fashion as a cultural signal: first through cult raw denim, then through a widening ready to wear offer. By the mid 2000s, the house formalizes its world through Acne Paper, and closes the era by stepping decisively onto the Paris stage with both the Palais Royal boutique and a high profile collaboration with Lanvin, signaling its transition from Scandinavian insider brand to global luxury player."},{"title":"Paris Runway Consolidation","year_range":"2009 - 2012","description":"With consistent Paris Fashion Week presence, Acne becomes seasonally legible: restraint, proportion play, and a cool, graphic styling language that’s easy to track from runway to runway. \n","images":["/api/assets/images/1771675757701-06m.webp","/api/assets/images/1771675759504-07m.webp","/api/assets/images/1771675795491-03fullscreen.webp","/api/assets/images/1771675797798-12fullscreen.webp","/api/assets/images/1771675829165-01fullscreen.webp","/api/assets/images/1771675831182-06fullscreen.webp","/api/assets/images/1771675832894-17fullscreen.webp","/api/assets/images/1771675868489-00010fullscreen.webp","/api/assets/images/1771675871009-00050fullscreen.webp","/api/assets/images/1771675899583-00010fullscreen_1_.webp","/api/assets/images/1771675901374-00060fullscreen.webp","/api/assets/images/1771675905387-00150fullscreen.webp","/api/assets/images/1771675955268-11fullscreen.webp","/api/assets/images/1771675957815-00010fullscreen.webp","/api/assets/images/1771675959821-00030fullscreen.webp","/api/assets/images/1771675961779-00070fullscreen.webp","/api/assets/images/1771675963776-00100fullscreen.webp"],"image_url":"/api/assets/images/1771675757701-06m.webp","caption":"With consistent Paris Fashion Week presence, Acne becomes seasonally legible: restraint, proportion play, and a cool, graphic styling language that’s easy to track from runway to runway. \n"},{"title":"House Codes Go Symbolic","year_range":"2013 - 2016","description":"Acne moves from “insider uniform” to a brand with clear shorthand: motifs, accessories momentum, and silhouettes that read instantly in photos. \n","images":["/api/assets/images/1771676108957-ACN_0023.1366x2048.webp","/api/assets/images/1771676110855-ACN_0034.1366x2048.webp","/api/assets/images/1771676112881-ACN_0088.1366x2048.webp","/api/assets/images/1771676115100-ACN_0242.1366x2048.webp","/api/assets/images/1771676117376-ACNE_003_1366.1366x2048.webp","/api/assets/images/1771676119284-ACNE_009_1366.1366x2048.webp","/api/assets/images/1771676121514-ACNE_013_1366.1366x2048.webp","/api/assets/images/1771676171802-Acne_001_1366.1366x2048.webp","/api/assets/images/1771676174123-Acne_003_1366.1366x2048.webp","/api/assets/images/1771676176441-LUX_1831.1366x2048.webp","/api/assets/images/1771676178280-LUX_1867.1366x2048.webp","/api/assets/images/1771676180121-LUX_1932.1366x2048.webp","/api/assets/images/1771676182005-LUX_2109.1366x2048.webp","/api/assets/images/1771676231774-_ARC0049.webp","/api/assets/images/1771676233545-_ARC0319.webp","/api/assets/images/1771676235319-_ARC0389.webp","/api/assets/images/1771676237671-_ARC0475.webp"],"image_url":"/api/assets/images/1771676108957-ACN_0023.1366x2048.webp","caption":"Acne moves from “insider uniform” to a brand with clear shorthand: motifs, accessories momentum, and silhouettes that read instantly in photos. \n"},{"title":"Icons, Platforms and Cultural Institution","year_range":"2017 - 2026","description":"Acne formalizes its pillars: denim becomes a codified platform, accessories become true icons, and the brand’s cultural output expands into physical space and programming.","images":["/api/assets/images/1771676390602-_UMB8264.webp","/api/assets/images/1771676392471-_UMB8418.webp","/api/assets/images/1771676393995-_UMB8578.webp","/api/assets/images/1771676395723-_UMB8968.webp","/api/assets/images/1771676423939-_ARC0077.webp","/api/assets/images/1771676425736-_ARC0153.webp","/api/assets/images/1771676427477-_ARC0187.webp","/api/assets/images/1771676460991-_AG30625.webp","/api/assets/images/1771676462811-_AG31014.webp","/api/assets/images/1771676510375-_ALE0024.webp","/api/assets/images/1771676512403-_ALE0087.webp","/api/assets/images/1771676513997-_ALE0416.webp","/api/assets/images/1771676515980-_ALE0680.webp","/api/assets/images/1771676562980-00001-Acne-Studios-Spring022-RTW-Paris-credit-gorunway.webp","/api/assets/images/1771676565378-00005-Acne-Studios-Spring022-RTW-Paris-credit-gorunway.webp","/api/assets/images/1771676567811-00005-acne-studios-fall-2025-ready-to-wear-credit-gorunway.webp","/api/assets/images/1771676572003-00011-acne-studios-fall-2025-ready-to-wear-credit-gorunway.webp","/api/assets/images/1771676573808-00016-acne-studios-fall-2025-ready-to-wear-credit-gorunway.webp","/api/assets/images/1771676575652-00027-acne-studios-fall-2025-ready-to-wear-credit-gorunway.webp"],"image_url":"/api/assets/images/1771676390602-_UMB8264.webp","caption":"Acne formalizes its pillars: denim becomes a codified platform, accessories become true icons, and the brand’s cultural output expands into physical space and programming."}]','[{"name":"U Rocka Wide Leg Jeans","image_url":"/api/assets/images/1771595529607-P01088761.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-u-rocka-wide-leg-jeans-blue-p01088761"},{"name":"Musubi Leather Crossbody Bag","image_url":"/api/assets/images/1771595551262-P01046978.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-musubi-small-leather-crossbody-bag-brown-p01046978"},{"name":"Distressed Logo Cotton Sweatshirt","image_url":"/api/assets/images/1771595576160-P01145270.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-distressed-logo-cotton-fleece-sweatshirt-black-p01145270"},{"name":"Deconstructed Embellished Straight Jeans","image_url":"/api/assets/images/1771595596310-P01145324.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-deconstructed-embellished-straight-jeans-blue-p01145324"},{"name":"Striped Cotton Sweater","image_url":"/api/assets/images/1771595617389-P01145275.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-striped-cotton-sweater-green-p01145275"},{"name":"Camero Party Shoulder Bag","image_url":"/api/assets/images/1771595630097-P01046972.avif","link":"https://www.mytheresa.com/euro/en/women/acne-studios-camero-party-leather-shoulder-bag-brown-p01046972"}]','2026-02-20 13:54:01','2026-02-21 12:23:01');
INSERT INTO "designers" VALUES(17,'Jacquemus','jacquemus','zhahk-MOOS','/api/assets/audio/1771677010120-Jacquemus.mp3','“Jacquemus” is the designer’s mother’s maiden name, the label is also framed as a dedication to her memory.','/api/assets/images/1771677012203-JACQUEMUS-LES-SCULPTURES-SPRING-2024-AD-CAMPAIGN.jpg','Simon Porte Jacquemus','2009','Paris, France','Simon Porte Jacquemus','[{"name":"Sculptural","description":""},{"name":"Youthful","description":""},{"name":"Romantic","description":""},{"name":"Refined","description":""}]','[{"title":"DIY Paris Arrival","year_range":"2009 - 2012","description":"Jacquemus builds a label in public: intimate, personal clothes paired with an instinct for image and community. The early identity leans Provençal in spirit: sunlight, simplicity, and emotion, filtered through a young Paris fashion-week ambition.","images":["/api/assets/images/1771677987699-IMG_5278ASEj.jpeg","/api/assets/images/1771677989457-F1000017.jpeg","/api/assets/images/1771677991545-F1010032.jpeg","/api/assets/images/1771677993844-F1010035.jpeg","/api/assets/images/1771677996979-project_47_.jpg","/api/assets/images/1771677999184-project_48_.jpg","/api/assets/images/1771678153662-project_47_.jpg"],"image_url":"/api/assets/images/1771677987699-IMG_5278ASEj.jpeg","caption":"Jacquemus builds a label in public: intimate, personal clothes paired with an instinct for image and community. The early identity leans Provençal in spirit: sunlight, simplicity, and emotion, filtered through a young Paris fashion-week ambition."},{"title":"Breakthrough Jacquemus","year_range":"2013 - 2017","description":"The house sharpens its codes: crisp silhouettes, playful proportions, and a cinematic Frenchness that reads instantly on camera. Industry recognition and collaborations expand the audience while keeping the tone intimate and auteur-driven.","images":["/api/assets/images/1771678280848-hubic.com_-273x410.webp","/api/assets/images/1771678283557-jacquemus-redoute-2-573x896.jpg","/api/assets/images/1771678285587-la-redoute-jacquemus.jpg","/api/assets/images/1771678359516-5565cc957e74a92a528380ab.format-webp.width-2880_FGFOasoFAJUNwPjj.webp","/api/assets/images/1771678361409-5565cc877e74a92a52837ff7.format-webp.width-1440_dsLSvFkPtnfLlcNZ.webp","/api/assets/images/1771678363372-5565cc8e7e74a92a5283803b.width-1440_p7jtx3zuTFQDXVNA.jpg","/api/assets/images/1771678365873-5565cc5f7e74a92de4285dff.format-webp.width-1440_OiXwSVuA1ICAAZpp.webp"],"image_url":"/api/assets/images/1771678280848-hubic.com_-273x410.webp","caption":"The house sharpens its codes: crisp silhouettes, playful proportions, and a cinematic Frenchness that reads instantly on camera. Industry recognition and collaborations expand the audience while keeping the tone intimate and auteur-driven."},{"title":"","year_range":"","description":"","images":[],"image_url":"","caption":""},{"title":"","year_range":"","description":"","images":[],"image_url":"","caption":""}]','[]','2026-02-21 12:53:29','2026-02-21 12:53:29');
